module.exports = /*#__PURE__*/JSON.parse('{"ScheduleButton":{"textbtn":"Schedule appointment"},"Header1Multipage":{"span":"Book your appointment"},"menuItems2":{"mainMenu":{"home":"Home","drThomas":"Dr. Thomas","press":"Press","international":"Patients Abroad","surgeries":"Surgeries","beforeAfter":"Before & After"},"subMenu":{"home":"Home","about":"About","team":"Team","blog":"Blog","press":"Press","international":"Patients Abroad","surgeries":"Surgeries","beforeAfter":"Before & After"}},"Home":{"metadata":{"title":"Dr. Thomas Benson, PhD - Plastic Surgeon","description":"Meet Dr. Thomas Benson, a leading expert in facial plastic surgery and a specialist in Deep Plane Facelift in Latin America. Excellence in innovative techniques for natural results, safety, and exclusivity."},"title":"Dr. Thomas Benson, PhD - Plastic Surgeon","description":"Meet Dr. Thomas Benson, a reference in facial plastic surgery and specialist in Deep Plane Facelift in Latin America. Excellence in innovative techniques for natural, safe and exclusive results.","h1":"Specialist and reference in facial surgeries.","pdesc":"For 15 years working with the highest standards of quality and excellence in facial rejuvenation.","videobtn":"Click here and watch the video!","scrolld":"Scroll down","abouth2":"A career marked by excellence.","aboutp":"Doctor of Medicine (PhD) from the prestigious University of São Paulo (USP), Brazil, and Doctor of Medicine (PhD) from the University of Hamburg (UKE - Universitätsklinik Eppendorf Hamburg) in Germany, Dr. Thomas built his career in the two most respected institutions in the medical field.<br/><br/> He is also the only plastic surgeon in Brazil with a specialist title from the European Board of Plastic Surgery (EBOPRAS), after taking his specialist exam in Brussels, Belgium and in Bern, Switzerland to obtain his certificate. Dr. Thomas Benson has specialist titles in Brazil being a full member of SBCP and also by the German government.<br/><br/> His training includes residency in General Surgery and Plastic Surgery at Hospital das Clínicas da USP, postgraduate studies in microsurgery at USP, one of the largest reference centers in facial and head and neck reconstructions in Latin America, did medical residency at Hospital Bogenhausen, in Munich, Germany, where he was responsible for the preceptorship of the training that year, where he worked as a plastic surgeon at Hospital Bogenhausen, after this period he specialized and accompanied several renowned surgeons in Brazil and in the USA where he perfected the face surgery techniques, including the Deep Plane Facelift.<br/><br/> Dr. Thomas is a member of the clinical staff of the Israelita Albert Einstein Hospital, Sírio Libanês Hospital, Moriah Hospital, today, he operates every day from Monday to Saturday, with seven surgeries per week at the only 6-star hospital in Brazil, Vila Nova Star (SP), the ultimate reference in highly safe and technological infrastructure.<br/><br/>","clinicah2":"Plastic surgery office in São Paulo.","clinicap":"Dr. Thomas Benson\'s Private Medical Office is located next to Ibirapuera Park on Av. Antônio Joaquim de Moura Andrade, in the upscale neighborhood of Vila Nova Conceição in São Paulo, a luxurious and comfortable environment with total security.","features":{"excellence":"Excellence structure","technology":"Cutting-edge technology","care":"Individualized care","safety":"Safety and multidisciplinary team"},"ct1h2":"We are one of the few exclusive teams that operate the face every day.","ct1p":"Excellence comes through daily practice repetition.","numberItems":{"cases":"Face cases per week.","experience":"Years of experience.","countries":"Countries seek Dr. Thomas\' excellence in Brazil.","surgeries":"Surgeries performed."},"hosph2":"Dr. Thomas performs surgeries every day at the only 6-star hospital in the country.","hospp":"Dr. Thomas is also a member of the clinical staff of other large hospitals, such as: Israelita Albert Einstein Hospital and Sírio-Libanês Hospital.","features2":{"1":{"text":"Best technologies."},"2":{"text":"Concierge with individualized care."},"3":{"text":"Post-surgical protocols."},"4":{"text":"Safety and exclusivity."}},"faqh3":"Questions some patients may have.","sectionp":"Pioneering, exclusivity, and a career marked by excellence and dedication. Dr. Thomas Benson is one of the foremost specialists in facial rejuvenation."},"About":{"metadata":{"title":"About || Dr. Thomas Benson","description":"Learn more about Dr. Thomas Benson, PhD in plastic surgery, the only Brazilian recognized by the European Board of Plastic Surgery and the German Society of Plastic Surgery. Author of the best-seller \'The Beauty of the Face\' and a reference in advanced techniques such as the Deep Plane Facelift."},"h2_1":"About","p1":"A specialist in facial surgeries, he is the only Brazilian with a specialization title from the European Council of Plastic Surgery and the German Society of Plastic Surgery.","h2_2":"Our History","atext1":"The path to excellence.","h2_3":"A career marked by excellence.","ct1h2":"We are one of the few exclusive teams that operate the face every day.","ct1p":"Excellence comes through daily practice repetition.","p2":"Pioneering, exclusivity, and a career marked by excellence and dedication. Dr. Thomas Benson is one of the leading specialists in facial rejuvenation."},"Team":{"metadata":{"title":"Team || Dr. Thomas Benson","description":"Meet the team of specialists led by Dr. Thomas Benson and discover the clinic\'s excellent infrastructure, focused on safety, comfort, and high-standard results in facial plastic surgery."},"h2":"Team","atext":"Meet our team of experts.","squadMembers":{"0":{"role":"Plastic Surgeon"},"1":{"role":"Manager"},"2":{"role":"Plastic Surgeon"},"3":{"role":"Plastic Surgeon"},"4":{"role":"Plastic Surgeon"},"5":{"role":"Plastic Surgeon"},"6":{"role":"Nurse"},"7":{"role":"Nurse"},"8":{"role":"Nurse"},"9":{"role":"Administration"},"10":{"role":"Concierge"}},"div":"Safety, comfort, and technology for every patient.","p":"Patient safety and comfort are the priority: premium, humanized care and infrastructure equipped with some of the most advanced technology for plastic surgery and recovery, as well as all the convenience for patients from all over Brazil.","h2_2":"Our patients say","span":"Accounts from patients who found excellence, care, and exceptional results.","div_2":"Surgeries performed in the best hospitals in the country.","p_2":"Dr. Benson performs his surgeries in hospitals with a team of highly qualified professionals and state-of-the-art equipment. This ensures that his patients receive the best possible care, from pre-operative to post-operative.","h3":"Questions some patients may have.","p_3":"Pioneering, exclusivity, and a career marked by excellence and dedication. Dr. Thomas Benson is one of the leading specialists in facial rejuvenation."},"teamTestimonials":{"role":"Patient","testimonials3":{"1":{"text":"Dr. Thomas is an amazing professional, I loved my procedure. He explained my procedure very carefully, answered all my questions, and the consultation was very enlightening and detailed. I found the entire team to be wonderful and attentive. I highly recommend him."},"2":{"text":"Gratitude is the word! Dr. Thomas is an excellent professional and very careful with his patients. At all times, he conveyed a sense of security. The result brought back my self-esteem and identity. To the entire team, thank you from the bottom of my heart. God bless you all."},"3":{"text":"It exceeded my expectations. My feeling is one of gratitude to everyone who took care of me with so much affection and attention, from the first consultation to the final follow-up. My friends and family were impressed with the result, and all I hear are compliments."},"4":{"text":"From the first consultation to the post-surgery sessions, the entire journey was surrounded by care and attention from him and his exceptional team. Everything proceeded in an atmosphere of tranquility, safety, and confidence, it couldn\'t have been better."},"5":{"text":"Super satisfied. Dr. Benson restored my self-esteem. I had a facial plastic surgery and it was the best decision I made. Great work, super attentive and caring staff. An excellent team. And Dr. Benson is incredible! I am just grateful for everything. I LOVED IT."},"6":{"text":"I can only express my gratitude for the wonderful professional and the very well-trained team. I received full support from the day of the consultation to the post-operative follow-ups. A human, honest, and very sensible doctor. He changed my self-esteem and my life. Eternal gratitude to everyone."}}},"Brands":{"h2":"National and International Certifications."},"pagePress":{"metadata":{"title":"Press || Dr. Thomas Benson","description":"See Dr. Thomas Benson\'s media appearances as a reference in facial plastic surgery. Featured in newspapers, magazines, TV shows, and documentary series, including \'The Hospital\' on Record."},"h2":"Press","atext":"Dr. Thomas Benson in the media: a reference in plastic surgery.","p":"Schedule your appointment now with <br/>Dr. Thomas Benson."},"Gallery2":{"pressItems":{"1":{"title":"Pioneering in Brazil: Dr. Thomas Benson has been a reference in the press since 2021."},"2":{"title":"Highlighted in Brazil with a live series on Record TV in 2021 in the program \'The Hospital\'."},"3":{"title":"Deep Plane Facelift: Dr. Thomas Benson is featured on Domingo Espetacular."},"4":{"title":"Celebrities undergo procedures and are attacked on social media."},"5":{"title":"Federal Council of Medicine authorizes the disclosure of \'before and after\' photos of procedures."},"6":{"title":"New rules for medical advertising."},"7":{"title":"Facial aesthetic procedures are on the rise during the pandemic."},"8":{"title":"PORTAL ETC - Dr. Thomas Benson: the best facial plastic surgeon in Latin America."},"9":{"title":"Rhinoplasty - Domingo Espetacular."},"10":{"title":"Dr. Thomas Benson - Health: Fat Grafting - Women\'s Program."},"11":{"title":"321 - Thomas Benson & Rafael de La Lastra."},"12":{"title":"Plastic surgery with international know-how in Alphaville - Vero Magazine."}}},"Blog":{"atext":"Stay updated on the main topics about plastic surgery!"},"BlogClient":{"placeholder":"Search..."},"BlogSlug":{"i":"Back to the blog page"},"BlogWidget2":{"placeholder":"Search...","h3":"Latest posts","span":"Posted on","li":"No results found.","h3_2":"Categories","categories":{"abdominoplastia":"Abdominoplasty","blefaroplastia":"Blepharoplasty","braquioplastia":"Brachioplasty","cicatriz":"Scar","lipoaspiração":"Liposuction","mamoplastia":"Mammoplasty","rinoplastia":"Rhinoplasty"}},"PressNewsPage":{"i":"Back to the press page","a":"Read the full article","p":"Schedule your appointment now with Dr. Thomas Benson.","PressItems":{"1":{"title":"Pioneering in Brazil: Dr. Thomas Benson has been a media reference since 2021.","article":"<p>A facial surgery specialist, Dr. Thomas Benson, graduated from the University of Hamburg, is now the only Brazilian with the title of specialist from the European Board of Plastic Surgery. The specialization was carried out in Germany and other European countries and validated in Brazil.</p><p>The surgeon\'s German medical degree had already been recognized by the University of São Paulo (USP), and today, he also engages with plastic surgery in other ways. Currently, Thomas participates as a volunteer in breast reconstructions performed at Albert Einstein.</p><p>Click the button below to continue reading this article on R7.</p><br/>"},"2":{"title":"Highlight in Brazil with live series on Record in 2021 on the show \'The Hospital\'.","article":"<p>With episodes in reality format, <em>The Hospital</em> documents the behind-the-scenes of Moriah Hospital, one of the largest in Latin America and a reference for its advanced procedures.</p><p>The documentary series has attracted public attention by highlighting the dedication, fragilities, losses, and achievements of health professionals.</p><p>Click the button below to continue reading this article on R7.</p><br/>"},"3":{"title":"Deep Plane Facelift: Dr. Thomas Benson is featured on Domingo Espetacular.","article":"<p>Facial harmonization procedures have never been more prominent than they are today. Among other reasons, social media and video calls, driven by remote work during the pandemic, have led to a 13.9% increase in facial aesthetic interventions between the biennia 2018-2019 and 2020-2021, according to the International Society of Aesthetic Plastic Surgery (ISAPS).</p><p>To discuss the topic, TV Record\'s ‘Domingo Espetacular’ interviewed Dr. Thomas Benson. In a program aired this past Sunday (20), the plastic surgeon explained how the ‘deep plane facelift’, the most advanced facial surgery in the world, works, which is a trend in the United States.</p><p>Click the button below to continue reading this article on IstoÉ.</p><br/>"},"4":{"title":"Celebrities undergo procedures and are attacked on social media.","article":""},"5":{"title":"Federal Council of Medicine authorizes the dissemination of \'before and after\' photos of procedures.","article":""},"6":{"title":"New rules for medical advertising.","article":""},"7":{"title":"Facial aesthetic procedures are on the rise during the pandemic.","article":""},"8":{"title":"PORTAL ETC - Dr. Thomas Benson: the best facial plastic surgeon in Latin America.","article":"<p>São Paulo-based plastic surgeon, Dr. Thomas Benson, specializes in the face. He is the only Brazilian with a specialization title from the European Board of Plastic Surgery and the German Society of Plastic Surgery. Additionally, he also holds specialization titles from the Brazilian and American Societies of Plastic Surgery.</p><p>He has just received the 2020 Quality Professional Award in the \'Plastic Surgeon\' category. This award recognizes professionals who stood out in their field of work over the past year. Dr. Benson graduated from USP and the University of Hamburg (Germany), and is successful on the internet with over 100,000 followers on Instagram.</p><p>He is so talented that his schedule is completely booked. But all dreams and work are only possible because of the support he receives from his family. For him, his wife and daughter are the foundation of everything in life.</p><br/>"},"9":{"title":"Rhinoplasty - Domingo Espetacular.","article":""},"10":{"title":"Dr. Thomas Benson - Health: Fat Grafting - Women’s Program.","article":""},"11":{"title":"321 - Thomas Benson & Rafael de La Lastra.","article":""},"12":{"title":"Plastic Surgery with International Expertise in Alphaville - Vero Magazine.","article":"<p>Sometimes we even forget. But often, the benefits of plastic surgery are directly linked to quality of life.</p><p>\'What drives me is seeing the return of my work in each patient\'s smile. They return to the office happier and with renewed self-esteem,\' says plastic surgeon Thomas Benson, 39, who specializes in improving people\'s lives through surgery.</p><p>The young doctor, who is currently the only one in Brazil with the title of specialist from the European Board of Plastic Surgery (European Board of Plastic Surgery), arrived in Alphaville through the most credible path: referrals. \'I used to attend more in the São Paulo region, but I already had patients in the neighborhood. They started to refer me to others who couldn’t always travel to my clinic in the capital,\' he explains.</p><p>That\'s when the surgeon, born in Brazil and raised in Germany, decided to open some days in his schedule to attend here. But don\'t think he only does a pre-consultation. He brings the whole team: \'In partnership with Dr. Karina Nunes, I take my team to Innovare Clinic, which has the multidisciplinary infrastructure needed for consultations,\' he explains.</p><br/>"}}},"patientsAbroad":{"metadata":{"title":"Patients Abroad || Dr. Thomas Benson","description":"Discover how patients from around the world choose Dr. Thomas Benson for excellence in facial plastic surgery. We offer personalized concierge service, accommodation, and a complete surgical experience in São Paulo."},"h2":"Patients Abroad","atext":"Global phenomenon of medical tourism.","p1":"Patients from various parts of the world travel to undergo procedures with Dr. Thomas.","p2":"Due to his technical excellence, exceptional results, and understanding of patient needs, people from various parts of the world choose to travel to São Paulo to have their procedure performed by Dr. Thomas.","div":"Our concierge will take care of your entire experience from start to finish.","p3":"Our concierge will assist you with accommodation in a prime location and with all transportation from your arrival until your post-surgical discharge, providing a complete experience to make you feel at home.","h3":"Global surgical experience:","p4":"Explore the impactful surgical experience in Brazil with Dr. Thomas Benson, PhD in Brazil and Germany. Patients from all over the world seek excellence in Dr. Thomas\'s practice.","progressData":{"0":{"label":"Brazil (surgical procedures performed) 70"},"1":{"label":"USA (surgical procedures performed) 20"},"2":{"label":"Europe (surgical procedures performed) 10"}},"p5":"Schedule your appointment now with Dr. Thomas Benson."},"Surgeries":{"metadata":{"title":"Surgeries || Dr. Thomas Benson","description":"Get to know the surgeries performed by Dr. Thomas Benson, including advanced techniques, pre- and post-operative care, and personalized procedures for natural, safe results with thin and imperceptible scars."},"h2":"Surgeries","atext":"Learn about the surgeries performed by Dr. Thomas Benson.","p":"Schedule your appointment now with Dr. Thomas Benson."},"SurgeriesPortfolio":{"filters":{"all":"All","facials":"Facial Surgeries","others":"Other Surgeries"}},"surgeriesItems":{"1":{"title":"Deep Plane Facelift","descr":"The Deep Plane Facelift surgery is considered one of the most advanced and innovative surgical techniques for facial rejuvenation, combining more natural and longer-lasting results with the benefit of virtually no visible scars."},"2":{"title":"Rhinoplasty","descr":"Recommended for those who want to reshape the size and proportion of the nose, rhinoplasty is one of the most sought-after surgeries for aesthetic purposes. It is also advisable for correcting structural problems of the nose."},"3":{"title":"Facial Fat Grafting","descr":"Facial Fat Grafting is a procedure that restores the youthful contour and shape of the face, as well as skin firmness, by applying fat taken from the abdomen or other parts of the body, purified and injected into areas that need volume restoration."},"4":{"title":"Lip Lift","descr":"One of the facial procedures that has been gaining attention in recent years is the lip lift, also called lip lifting. It lifts the upper lip, correcting the natural droop (which fillers cannot correct) and adds more volume."},"5":{"title":"Forehead Lift","descr":"Furrowed forehead, expression lines, wrinkles, and a tired look. These are just some of the consequences of aging, and among plastic surgeries, the forehead lift is an alternative that helps improve appearance."},"6":{"title":"Blepharoplasty","descr":"The eye area, when showing the effects of aging, gives a tired appearance, causing discomfort and annoyance. Blepharoplasty is indicated for patients with typical aging changes, such as excess skin on the eyelids."},"7":{"title":"Dermal Fillers","descr":"Hyaluronic acid is best indicated for facial grooves that form over the years (such as the nasolabial fold) and around the lips. It can also be used to enhance lips in patients with thin lips."},"8":{"title":"Otoplasty","descr":"Otoplasty or ear plastic surgery corrects protruding ears. Protruding ears are characterized by the ears being set away from the head, making them more noticeable and giving the impression that they are larger."},"9":{"title":"Brachioplasty","descr":"Brachioplasty is indicated for patients with flaccidity in the arm region. This can occur due to poor eating habits, a sedentary lifestyle, or genetic factors. This aesthetic issue in the arms can often cause discomfort and insecurity."},"10":{"title":"Abdominoplasty","descr":"Like liposuction, abdominoplasty is a surgery to remove excess skin from the abdomen, reshaping the area. It is highly recommended for patients who have recently been pregnant or have undergone bariatric surgery."},"11":{"title":"Liposuction","descr":"Involves the suction of fat through a cannula to improve body contour and reshape the body\'s silhouette. Best indicated for localized fat areas that do not decrease with exercise and diet."},"12":{"title":"Breast Reconstruction","descr":"Breast reconstruction is achieved through various plastic surgery techniques that attempt to restore the breast considering shape, appearance, and size after the removal of a tumor (lumpectomy) or the entire breast (mastectomy)."},"13":{"title":"Gynecomastia","descr":"Gynecomastia correction is indicated in cases related to hormonal influences during youth and does not regress after puberty. In cases related to weight gain, it can also be performed if the condition does not reverse."},"14":{"title":"Mammoplasty","descr":"Breast reduction mammoplasty involves reducing large breasts or increasing small breasts, lifting and symmetry. Additionally, it can be used for breast reconstruction in cases of cancer."},"15":{"title":"Breast Implants","descr":"Silicone implant surgery is the most performed plastic surgery in Brazil. They increase breast volume. It is indicated for small volume breasts, with slight sagging, asymmetries, and reconstructions after oncological surgeries."},"16":{"title":"Post-Weight Loss Surgery","descr":"If you have experienced dramatic weight loss, either through diet and exercise or bariatric surgery (obesity surgery), and have reached your ideal weight, then you might be a good candidate for this type of surgery."},"17":{"title":"Combined Surgeries","descr":"Combining plastic surgeries has been a frequently used resource. The great advantage of these combined surgeries is the good result obtained in a single procedure, which brings significant time and money savings for the patient."},"18":{"title":"Labiaplasty","descr":"Labiaplasty or intimate surgery involves the correction of hypertrophy (enlargement) of the small labia in the female genital area. Generally, removing excess fat or skin can correct the enlargement."}},"SurgerieItemPage1":{"i":"Back to the surgery page","p":"Schedule your appointment with Dr. Thomas Benson now.","deep-plane-facelift":{"title":"Deep Plane Facelift","descr":"The Deep Plane Facelift surgery is considered one of the most advanced and innovative surgical techniques for facial rejuvenation, combining more natural and lasting results with the benefit of virtually no visible scars.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Learn more</h2><p>The main feature of the Deep Plane Facelift, as the name suggests, is its action in a deeper layer of the muscles. It acts directly between the SMAS system, or Superficial Musculo-Aponeurotic System, which causes signs of facial aging, and the deeper muscle layer responsible for facial expression.</p><p>The primary goal of the Deep Plane Facelift is the release and repositioning of muscle and fat layers without causing tissue tension, resulting in a more youthful appearance without the “stretched skin” look.</p><p>In general, facial tissue ligaments are released for natural repositioning throughout the face and neck, restoring the shape and volume of the cheeks without the need for fillers or fat. The ligaments that anchor the jaw are also released to lift it, creating a smoother, sharper jawline appearance.</p><p>Besides the face, it is also used in conjunction with cervicoplasty, allowing for greater refinement of the neck and jawline area with more lasting results.</p><br><div><div class=\\"ratio ratio-16x9\\"><iframe width=\\"1280\\" height=\\"720\\" src=\\"https://www.youtube.com/embed/741HqtRgGIM?si=sos8FUDdaEusQeR4\\" title=\\"Deep Plane: Why I chose this innovative technique\\" frameborder=\\"0\\" allow=\\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\\" allowfullscreen></iframe></div><p class=\\"pt-2 small\\"><strong>Why I chose the innovative Deep Plane Facelift technique</strong><br><em>Explanation by Dr. Thomas Benson</em></p></div><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Deep Plane vs. Traditional Facelifts</h2><p>One of the biggest concerns of patients is achieving more natural results, without the stretched appearance common to traditional techniques.</p><p>The reason for this is that in other more common techniques, only the more superficial skin layers are repositioned and sutures are applied to lift the SMAS muscle set, leaving the skin firmer but without eliminating the problem of sagging cheeks.</p><p>As a result, many surgeons end up correcting with fat grafting, often making the cheeks more noticeable.</p><p>Besides more natural results, recovery from a Deep Plane Facelift is faster and simpler. It is common in other types of facelift for blood vessels to break, causing larger bruises and slower recovery.</p><br><div><div class=\\"ratio ratio-16x9\\"><iframe width=\\"1280\\" height=\\"720\\" src=\\"https://www.youtube.com/embed/gPs3-B48ffY?si=aHDo7uWaKcrINxR2\\" title=\\"How the Deep Plane technique works - Thomas Benson\\" frameborder=\\"0\\" allow=\\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\\" allowfullscreen></iframe></div><p class=\\"pt-2 small\\"><strong>How does the Deep Plane Facelift technique work?</strong><br><em>Commentary by Dr. Thomas Benson</em></p></div><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Recovery and Scars</h2><p>Recovery after a Deep Plane Facelift generally involves few bruises and quicker recovery as there are no cuts in blood vessels between the muscle and the skin. Some bruising and swelling around the repositioned areas may appear in the first few days and will gradually disappear.</p><p>Pain medications may be prescribed to help the patient feel more comfortable during the healing process. It is also important to use cold compresses to relieve swelling, along with rest for recovery.</p><p>The Deep Plane Facelift has incisions that heal with minimal or no visible scars. As in this technique the skin is not separated from the muscles, there is no tension on the incision lines after they are closed, allowing the incision to heal as an imperceptible line.</p><p>Main benefits of the Deep Plane Facelift</p><ul><li>Shorter surgical time</li><li>More natural results</li><li>Restoration of natural volume</li><li>Removal of excess skin</li><li>Smoother, youthful-looking skin</li><li>Faster recovery</li><li>Imperceptible scars</li><li>Longer-lasting results</li></ul><br><div><div class=\\"ratio ratio-16x9\\"><iframe width=\\"1280\\" height=\\"720\\" src=\\"https://www.youtube.com/embed/1rpzysLsi6w?si=RWWz_-x14TKRUYSv\\" title=\\"Deep Neck Lift explained by Dr. Thomas Benson\\" frameborder=\\"0\\" allow=\\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\\" allowfullscreen></iframe></div><p class=\\"pt-2 small pb-0 mb-0\\"> <strong>Deep Necklift explained by Dr. Thomas Benson</strong><br><em>Watch the video</em></p></div></div>"},"rinoplastia":{"title":"Rhinoplasty","descr":"Indicated for those who want to shape the size and proportion of the nose, rhinoplasty is one of the most sought-after surgeries for aesthetic purposes. It is worth noting that this type of surgery is also advisable to correct structural problems of the nose.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Learn more</h2><p>Among the various plastic surgery procedures currently available, rhinoplasty (the technical name for nose surgery) is the most complex type to be performed with excellence.</p><p>The nose is one of the most striking features of a person\'s face, and small irregularities in its shape can cause serious self-esteem issues for the patient. Currently, developed rhinoplasty techniques can correct these imperfections in a way that harmonizes facial symmetry and aids in better respiratory system function.</p><p>Besides facial harmony, in practice, rhinoplasty can improve breathing, sense of smell, and bring more quality of life to those who suffer from both acquired and congenital deformities. In our clinic, we mainly use the structured technique, which is a less aggressive technique with more natural and aesthetically balanced results for the face.</p><p>It is a technique used by more experienced surgeons in facial procedures, separating all the subunits of the nose and usually removing cartilage from the septum, making precise modifications to the structures. As a result, the outcome is much more durable and with less risk of future changes.</p><p>In general, the doctor evaluates facial proportion, nasal angles, skin characteristics, and what needs to be improved for quality of life as well. That is why it is very important to choose a doctor carefully, as rhinoplasty is an artisanal process that requires precise and accurate skills to ensure everything works as expected.</p><p>Moreover, in our clinic, you will find the support of qualified professionals to answer all your questions, whether about the surgical process or postoperative care. If you are considering undergoing rhinoplasty, schedule a consultation and get all the necessary information to help you make this decision.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Advantages of the structured technique</h2><p>It is important to note that after rhinoplasty surgery, the nose continues to be affected by various forces, such as the pressure generated by breathing in the airways. Consequently, the scar tissue that forms around the positioned cartilages may undergo small deformations over time, even altering the position of these cartilages.</p><p>For this reason, Structured Rhinoplasty aims to strengthen this nasal structure, contributing to more lasting results, in addition to greater precision in sculpting the cartilage, providing a more natural and harmonious result.</p><p>Furthermore, depending on the case, the surgeon may prioritize internal incisions in the nose, which ensures they remain completely imperceptible.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Anesthesia</h2><p>With advancements in medication and patient monitoring and control equipment technology, general anesthesia has become the safest when well indicated.</p><p>We must consider very important factors such as: pre-existing diseases, preoperative exams, competent professionals, modern equipment, and hospitals with infrastructure suitable for surgical procedures.</p><p>It is of utmost relevance to know the patient\'s history and have a clinical evaluation that allows indicating the procedure.</p><p>Proper monitoring using all the technological resources accessible today allows for the control of heart rate, blood pressure, oxygenation, airway control, maintenance of body temperature, prevention of thrombosis, and even determination of patients\' level of consciousness.</p></div>"},"lipoenxertia-facial":{"title":"Facial Fat Grafting","descr":"Facial Fat Grafting is a procedure that restores the contour and youthful shape of the face, as well as skin firmness through the application of fat removed from the abdomen or other parts of the body, purified and injected into areas that need volume recovery.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Learn more</h2><p>Facial Fat Grafting is one of the techniques that has most revolutionized facial lifting plastic surgeries, as well as being one of the most advanced techniques in plastic surgery in recent years.</p><p>Various facial lifting procedures were created with the aim of facial rejuvenation, most of them resulting in more extensive surgery and less natural results. Something that was noticed during this period is that the face ages not only due to sagging from lack of support but also from losing the natural volume of cheeks, jawline, and under the eyes.</p><p>It is a procedure that uses fat removed from the abdomen or other parts of the body, purified and applied to areas of the face that have lost volume, which in addition to offering more natural results also contributes to skin quality and reduction of small wrinkles and imperfections.</p><p>This procedure restores the contour and youthful shape of the face, as well as skin firmness. Unlike fat grafting procedures that use previous techniques, in Facial Fat Grafting, the fat undergoes processing and purification, maximizing and improving the quality of the skin and tissues in general.</p></div>"},"lifting-labial":{"title":"Lip Lift","descr":"One of the facial procedures that has been gaining attention in recent years is the lip lift, also called lip lift or lip lifting. It raises the upper lip, correcting natural sagging (which fillers cannot correct) and adds volume.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Learn more</h2><p>The Lip Lift surgery is a procedure that can be performed on both older people for facial rejuvenation, correcting the natural sagging of the upper lip, and on young people who aim for lip augmentation, as lifting the upper lip adds more volume, exposing more of the upper teeth and providing a more harmonious smile.</p><p>With aging, one of the consequences is the loss of fat in the lips, causing them to sag due to loss of support. Lip lifting is the most indicated procedure for those who want to permanently correct lip height and volume, avoiding the need for constant lip filler applications.</p><p>When you hear the term Lip Lifting, or Lip Lift, it generally refers to an upper lip lift. The operation can be adapted to lift different regions of the lip, making them more shaped and with a more defined contour.</p><p>By correcting cases of patients who have a large distance between the nose and the upper lip, a more harmonious appearance is given to the rest of the face. For this reason, there are younger patients who have a longer upper lip who benefit immensely from this surgery. When performed on older patients, it restores the youthful appearance of the face. This subtle alteration makes people look years younger and rejuvenated.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">More natural results</h2><p>The Lip Lift procedure is often performed in conjunction with laser applications. For those who mainly desire volume increase, fat grafting (or lipofilling, a globally recognized procedure where a portion of fat is removed from the abdomen or other parts of the body, purified, and injected into the necessary areas) is often used in conjunction, which in addition to offering more natural results also contributes to skin quality and the reduction of small wrinkles and imperfections.</p></div>"},"lifting-frontal":{"title":"Forehead Lift","descr":"Furrowed forehead, expression lines, wrinkles, and tired look. These are just some of the consequences of aging, and among plastic surgeries, the brow lift is an alternative that helps improve appearance.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Learn more</h2><p>The Brow Lift is a surgical procedure for facial rejuvenation, softening expression lines and wrinkles in the forehead area. The surgeon lifts the skin and tissues of the upper face with the aid of a high-precision endoscopic camera, resulting in a younger and refreshed appearance.</p><p>The Brow Lift is a surgical procedure for facial rejuvenation, softening expression lines and wrinkles in the forehead area. The surgeon lifts the skin and tissues of the upper face with the aid of a high-precision endoscopic camera, resulting in a younger and refreshed appearance.</p><p>The technique involves making small incisions so that the ligaments and muscles are repositioned in such a way that the face gains a younger appearance, minimizing aging, reducing lines, and possibly arching the eyebrows, with practically imperceptible scars.</p><p>Due to the smaller incisions, patients undergoing a brow lift with endoscopic approach experience a shorter recovery period, returning to their normal activities sooner and with more lasting results compared to more commonly performed methods.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Combined techniques</h2><p>Before opting for a brow lift, it is essential to talk to the surgeon to align expectations and possible results. The brow lift brings great results when performed individually, but it is possible to go further and renew the overall appearance by combining it with other procedures.</p><p>Some of the main techniques often combined with the brow lift are: the facelift, which rejuvenates the face area, and blepharoplasty for the eye area, thus the results can be further enhanced.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Endotine® Forehead Device</h2><p>One of the technologies we use in our surgeries is the Endotine® Forehead Device, which is an innovative solution specifically designed to lift the forehead tissue during the brow lift surgery. Its unique structure provides multiple points of contact with the forehead tissue, creating a more uniform and smooth distribution of holding force.</p><p>Other options, such as screws and sutures, usually provide only one point of contact that can tear the soft tissues, adversely affecting the reliability of the eyebrow lift.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Post-surgery care</h2><p>Recovery after a brow lift via endoscopy involves a simpler postoperative period compared to more traditional techniques. In ten days, most patients can already resume their normal activities.</p><p>In the first few days, it is common to see bruising and swelling in the incision area, so the recommendation is to keep the head elevated whenever possible, applying cold compresses to help reduce swelling. Some patients experience headaches between 24 and 48 hours after the surgery. The most visible signs of the surgery should disappear after three weeks, and normal hair growth will resume in the following months.</p><p>Among the recommendations, it is worth noting that the patient can only wash their hair after three days and should take care of the dressings as instructed by the doctor, avoiding the use of makeup for a few days. It is also necessary to avoid physical exertion, such as lowering the head, for example. Avoiding sun exposure is also important to protect the scar.</p><p>In cases of pain or discomfort, talk to the doctor about analgesics and anti-inflammatory medications that can be used.</p></div>"},"blefaroplastia":{"title":"Blepharoplasty","descr":"The eye region, when showing the effects of aging, gives a tired appearance, causing discomfort and inconvenience. Blepharoplasty is indicated for patients who present typical signs of aging, such as excess skin on the eyelids.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Learn more</h2><p>Drooping eyelids, crow\'s feet, and tired dark circles are common signs of aging in the eye region. To correct these problems, blepharoplasty is a plastic surgery that can alleviate these issues, rejuvenating the face and improving the patient\'s self-esteem and well-being.</p><p>Blepharoplasty is the procedure of lifting the eyelids, in which the surgeon eliminates fat bags and minimizes the natural sagging from aging. The upper drooping eyelids are the result of excess skin laxity, and the lower eyelids become swollen; fat bags develop with age due to fat prolapse under the eyes. These changes generally contribute to a more aged appearance.</p><p>For the upper eyelid, all individual lines and folds are marked to keep the incisions as invisible as possible along the natural creases. The incision is made, and a precise amount of excess fat, muscle, and loose skin contributing to the problem is removed.</p><p>On the lower eyelid, the incision is made in an imperceptible location, just a few millimeters below the lash line and along the folds of the lower eyelid. Again, a precise portion of skin, fat, and muscles is carefully removed. Extremely fine sutures are then used to meticulously close the incisions, minimizing the visibility of any scars.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Combined techniques</h2><p>To undergo blepharoplasty, the patient needs to be in good physical health and align emotional expectations with the surgeon. In addition to a medical evaluation, the patient will likely need to undergo blood lab tests.</p><p>The use of anticoagulant medications before surgery is not advisable. Alcohol and smoking should also be avoided before the procedure, and an absolute fast is required 8 hours before the surgery.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Post-surgery care</h2><p>After surgery, it is common for the operated area to be sensitive and a bit swollen, so the rest period varies between one week and a month. During this period, extra care is required to ensure safe healing and adequate recovery.</p><p>Therefore, pay attention to these tips:</p><ul><li>Avoid exposure to the sun, wind, and cold;</li><li>Avoid rubbing the eyes;</li><li>Do not lie on your side;</li><li>When applying compresses, use saline solution;</li><li>Sleep with two pillows to keep the head elevated;</li></ul><p>In case of doubt, schedule a follow-up appointment with the doctor;</p></div>"},"preenchimento-cutaneo":{"title":"Dermal Fillers","descr":"The best indication for hyaluronic acid is in the facial grooves that form over the years, such as the nasolabial fold and the grooves around the lips. It can also be used to enhance the lips in patients with thin lips.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Learn more</h2><p>Over time, it is inevitable that expression lines, facial grooves, wrinkles, and signs of aging become visible on our skin. Therefore, maintaining elasticity, recovering collagen, and skin consistency is a challenge. To solve these problems, dermal fillers are one of the possible treatments.</p><p>With a minimally invasive technique, the procedure involves applying hyaluronic acid to the desired area, usually with an injection and local anesthesia. In addition to these advantages, unlike other procedures, the patient needs to take some post-filler care but does not need to rest.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Results</h2><p>In practice, the results of dermal fillers last from 15 to 18 months. With hyaluronic acid, wrinkles are literally filled, and expression lines appear smoother and more discreet. Besides this purpose, this technique is also highly recommended for patients who want to enhance the lips, contour the cheekbones, and correct the so-called “smile lines” (nasolabial fold).</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Care</h2><p>Every aesthetic procedure requires medical evaluation, and it is always recommended that the patient aligns their expectations with reality. With impressive effects, dermal fillers are indeed an alternative for signs of aging, but it is important to remember that aging is a natural process.</p><p>Therefore, besides the aesthetic procedure, it is never too much to reinforce some care such as:</p><ul><li>Taking care of your diet;</li><li>Staying hydrated regularly;</li><li>Avoiding excessive sun exposure;</li></ul></div>"},"otoplastia":{"title":"Otoplasty","descr":"Otoplasty or ear plastic surgery corrects prominent ears. Prominent ears are those that stand out from the head, making the ears more noticeable and giving the impression that they are larger.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Learn more</h2><p>The so-called “prominent ear” that causes disproportion in the size and shape of the ears is a problem that affects 2% to 5% of the population according to the Brazilian Society of Plastic Surgery.</p><p>To correct this problem, otoplasty is the most recommended plastic surgery. In practice, otoplasty is performed through an incision behind the ear. During the surgery, the doctor removes a small part of the cartilage and performs a process to position the ears as adequately as possible, bringing the ears closer to the head.</p><p>After closing the incisions, a dressing is placed around the ears for a period of 24 hours to protect the operated area.</p><p>The results of otoplasty are generally very positive and the surgery does not leave deep scars, considering that the stitches are hidden behind the ears. However, it is worth remembering that not every case will have 100% symmetry, as nature itself is asymmetrical.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">How and when to perform</h2><p>The earlier the surgery is performed, the better the result will be. It is common for parents to be concerned about the best time to perform otoplasty on children born with prominent ears, and it is no wonder, as otoplasty is a surgical intervention.</p><p>However, the age range of 5 to 7 years is quite recommended for surgery, as at this stage the child\'s ear is fully formed and over time, the disproportion and discomfort can become even greater.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Postoperative care</h2><p>When the surgeon closes the incisions, the person automatically has a dressing around the surgery in the form of a helmet for a period of 24 hours. After this time, the helmet is replaced by a compression band that needs to remain in place for a month, and to maintain the success of the surgery, the person naturally needs to take some care.</p><p>They are:</p><ul><li>Avoid sun exposure;</li><li>Do not practice sports;</li><li>Avoid touching and scratching the area;</li></ul><p>By following these guidelines, the patient avoids breaking the stitches, infections, and the possibility of a new surgery.</p></div>"},"braquioplastia":{"title":"Brachioplasty","descr":"Brachioplasty is indicated for patients with sagging in the arm area. This can occur due to poor eating habits, sedentary lifestyle, or genetic factors. Often this aesthetic problem in the arms can be bothersome and generate insecurity.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Learn more</h2><p>If you have localized fat and sagging in the arms, popularly known as \\"bat wings,\\" the so-called brachioplasty or arm lift may be the solution.</p><p>Lasting two hours, the surgery is performed under local anesthesia and sedation. During the procedure, the surgeon makes an incision on the inner part of the arm and thus removes the excess skin and fat from the area.</p><p>It is common for brachioplasty to also be complemented with other procedures, and in these cases, the patient also undergoes general anesthesia.</p><p>It is important to remember that the surgery is in a very exposed area and, therefore, it is common for scars to appear until the complete recovery period, which can vary between one and two years.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">What is the best technique?</h2><p>Many people wonder if brachioplasty is the best solution, and indeed, this is a very pertinent question. At the time of evaluation, the surgeon can assess together with the patient which is the best option. In some cases, the increase in fat can be resolved with liposuction.</p><p>In others, a balanced diet and healthy habits can solve the problem. But if nothing works, brachioplasty is an option that brings very positive results. It is important to understand the process and clarify doubts with a trusted specialist.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Care</h2><p>After the surgery, patients should rest for a period of three to five days. In addition, it is necessary to keep the arms close to the body for up to three weeks. It is good to avoid physical effort in the area during the first month so that tissue healing occurs without the enlargement of scars.</p><p>The patient should also wear compression garments for one or two months to reduce swelling in the operated area. And finally, if possible, lymphatic drainage is a good idea to optimize the absorption of edema during this recovery phase.</p></div>"},"abdominoplastia":{"title":"Abdominoplasty","descr":"Just like liposuction, abdominoplasty is a surgery performed to remove excess skin from the abdomen, reshaping the area. It is highly recommended for patients who have recently gone through pregnancy or have had bariatric surgery.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Learn more</h2><p>Just like liposuction, abdominoplasty is a surgery that can be used to reshape the abdominal area. It is highly recommended for patients who have recently gone through pregnancy or have had bariatric surgery. Abdominoplasty involves treating excess skin, localized fat, and correcting the separation of the abdominal muscles.</p><p>The surgery lasts an average of 3 hours, and during this period, the doctor needs to make an incision in the lower abdomen. After this incision, the skin and fat are separated from the muscle wall, allowing the muscles that reinforce the abdominal wall to be brought closer together. After that, the surgeon removes the excess skin and fat and closes the incision.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Before and after the surgery</h2><p>Before the surgery, the patient should avoid taking medication, smoking, and drinking alcohol, and follow the rule of total fasting for eight hours before the surgery. After being discharged (the patient can usually go home the day after the surgery), the rest period can vary from 10 days to two months, but regardless of this time, it is necessary to follow some care guidelines to ensure the best possible results from the abdominoplasty.</p><p>They are:</p><ul><li>Sleep on your back with your legs always bent (at least for the first 15 days);</li><li>Shower baths are possible the day after the surgery. The surgical team will change the dressings after 4 days;</li><li>Wear a compression garment and compression stockings (the compression garment should only be removed for bathing because it relieves pain and prevents complications with scars). In the case of compression stockings, they should only be removed when the person resumes daily activities;</li><li>Dressing changes (the first change should be done 4 days after the surgery by the medical team, delicately following medical guidelines);</li><li>Light physical exercises (it is not recommended for the patient to lift weights after the surgery, but in this case, it is good to move the legs every two hours to avoid clots in the operated area);</li></ul></div>"},"lipoaspiracao":{"title":"Liposuction","descr":"It consists of aspirating fat through a cannula to improve body contour and reshape the body\'s silhouette. It is best indicated for areas of localized fat that do not decrease with exercise and diet.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Learn more</h2><p>The famous “lipo,” also known as liposuction, is a highly sought-after and well-known surgery among women who want to reshape their abdomen and body by reducing localized fat.</p><p>In addition to the abdomen, liposuction can also be performed on other areas of the body such as the waist, upper and lower back, flanks, inner thighs, and even the arms.</p><p>The team uses saline solution and medication on the fat to be aspirated, and in the end, all incisions are closed and protected with a dressing, followed by a compression garment to reduce swelling. Liposuction lasts an average of 1 to 3 hours, depending on the case.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Varieties of liposuction</h2><p>Liposculpture is a variation of liposuction where, in addition to the usual liposuction procedures, fat (known as fat grafting) removed from the patient is placed in other areas.</p><p>The most frequent area where fat is injected is the gluteal region (buttocks), but other areas can be addressed, such as localized depressions (congenital or resulting from previous surgeries), facial folds (nasolabial fold), and lips.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Post-surgery care</h2><p>For the results to be more effective, the patient needs to invest in recovery and postoperative care. For example, the compression garment should be worn most of the time during the first month and should only be removed for bathing. In the second month, it should still be worn for 12 hours. Additionally, it is important to drink plenty of water to keep the body hydrated and adopt a healthy, balanced diet.</p><p>If possible, lymphatic drainage is also a good option to enhance results. It is important for the patient not to smoke for at least a month after the surgery and to avoid strenuous physical exercise. Sun exposure should also be avoided. Each case has its particularities, but by following these care guidelines, the patient has a better chance of a smooth recovery and healing.</p></div>"},"reconstrucao-mamaria":{"title":"Breast Reconstruction","descr":"Breast reconstruction is achieved through various plastic surgery techniques that aim to restore the breast considering its shape, appearance, and size after the removal of the tumor (lumpectomy) or the entire breast (mastectomy).","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Learn more</h2><p>Indicated for women who had their breasts removed due to a health problem or for those who want to change the shape, size, and appearance of their breasts, breast reconstruction is a highly sought-after option.</p><p>The surgery time varies greatly depending on the patient\'s situation, and it is common for the surgeon to opt for complementary procedures in addition to breast reconstruction.</p><p>Generally, breast reconstruction is divided into phases, from evaluation to the removal of excesses and reconstruction of the glands, and there is no rule for what comes first, as each case has its particularities.</p><p>During the surgery, it is possible to reconstruct from the nipple to the entire areola. For this type of procedure, it is also worth highlighting the need for general anesthesia.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Surgery preparation</h2><p>Regardless of the context, everyone undergoing breast reconstruction needs to follow some steps. The first is a conversation with the specialist to align expectations.</p><p>After that, laboratory tests such as blood count, electrocardiogram, ultrasound, and mammography are needed.</p><p>The use of medication should also be stopped, especially if they are aspirin or anti-inflammatory drugs and natural remedies.</p><p>If the patient smokes, it is important to quit smoking before surgery, and finally, it is necessary to fast for eight hours before the procedure.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">After the procedure</h2><p>In addition to avoiding physical exertion and sun exposure, the patient needs to be aware of a temporary drain placed on the skin for blood and fluid.</p><p>Following hygiene and dressing care and taking medication helps reduce the risk of infection.</p><p>Additionally, it is not advisable to smoke after surgery, and it is recommended to have an adequate diet to ensure successful recovery. As with other surgeries, it is necessary for the patient to follow up with the doctor, informing the specialist of all the surgery conditions.</p></div>"},"ginecomastia":{"title":"Gynecomastia","descr":"Gynecomastia correction is indicated in cases related to hormonal influences in youth that do not regress after puberty. In cases related to weight gain, surgery can also be performed if there is no reversal of the condition.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Learn more</h2><p>Gynecomastia is a condition in which men have an increase in tissue in the mammary glands, affecting 60% of men.</p><p>Surgery is generally indicated for men who, even after puberty, continue to suffer from this problem, and the surgery time varies greatly depending on the gland condition, usually lasting between one and two hours.</p><p>In cases where there is only fat accumulation and the gland does not increase much, liposuction can solve the problem.</p><p>However, when the mammary gland is hypertrophic, the surgeon needs to make a simple incision to remove this excess.</p><p>Depending on the case, combined techniques may be necessary, especially when there is excess skin and flaccidity.</p><p>In this situation, in addition to removing the tissues, the specialist needs to adjust the position of the nipple and areola so that the chest is in harmony with the nipples.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Before and after</h2><p>In addition to medical evaluation, the patient undergoing gynecomastia needs to perform routine preoperative tests and breast evaluation with ultrasound.</p><p>By following these recommendations, the patient\'s recovery occurs gradually and healthily, and in case of any symptoms such as shortness of breath, chest pain, or abnormal heartbeats, the surgeon should be consulted.</p><p>After surgery, the patient needs to follow some care guidelines, such as:</p><ul><li>Sleep on your back for 30 days;</li><li>Attend medical follow-ups;</li><li>Do not smoke for 15 days after surgery;</li><li>Wear an elastic vest to improve skin adherence to the chest for 30 days;</li></ul></div>"},"mamoplastia":{"title":"Mammoplasty","descr":"Mammoplasty involves the reduction of large breasts or the augmentation of small breasts, lifting, and symmetrizing them. Additionally, it can be used for breast reconstruction in cases of cancer.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Learn more</h2><p>Just like silicone implants, mammoplasty is a breast surgery, with the difference that it can increase or reduce the size of this part of the body.</p><p>In the case of augmentation mammoplasty, the surgeon also makes incisions in the area to implant the prosthesis with the chosen shape, texture, and size.</p><p>In reduction mammoplasty, the surgeon makes incisions that start around the areola and go down to the mammary fold and horizontally, creating an inverted “T” shape.</p><p>After that, the mammary tissue is mobilized, and the excess breast tissue is reduced according to the patient\'s needs.</p><p>In addition to reducing or increasing the breasts, mammoplasty is also indicated for reconstructing breasts that have been damaged by accidents or removed due to cancer.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Before and after</h2><p>As with other procedures, it is important to remember that the patient must be confident in their decision to undergo mammoplasty. Routine tests such as blood tests, electrocardiograms, and imaging exams like mammography and ultrasound should be performed, following all medical guidelines regarding fasting and hospitalization time.</p><p>After mammoplasty, the patient should take extra care during the postoperative phase, such as:</p><ul><li>Wearing a surgical or support bra for 30 days;</li><li>Avoiding sleeping on the side for a month and not sleeping on the stomach;</li><li>Avoiding physical exercise for 90 days;</li><li>Not applying cream to the surgical incision;</li><li>Gently caring for hygiene and the stitches;</li></ul></div>"},"protese-de-mama":{"title":"Breast Implants","descr":"Silicone implant surgery is the most performed plastic surgery in Brazil. They increase breast volume. It is indicated for breasts with small volume, mild sagging, asymmetries, and reconstructions after oncological surgeries.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Learn more</h2><p>A favorite among women who want to increase the volume and shape of their breasts, breast implants are a highly sought-after surgery in all plastic surgery clinics.</p><p>With epidural or general anesthesia, breast implant surgery lasts an average of two hours. During the procedure, the surgeon makes an incision in the inframammary fold or the armpit area. Usually, the inframammary fold option is the most used, considering the access to the area where the implant will be placed and hidden by the bra.</p><p>It is important to remember that the implant\'s position depends greatly on the patient\'s anatomy, but in a general context, there are two options: below the mammary gland (known as subglandular/subfascial) or below the pectoral muscle (submuscular).</p><p>In addition to routine preoperative exams, it is common for the surgeon to request complementary imaging exams such as breast ultrasound or mammography.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Before and after</h2><p>Talking to the doctor and assessing the best shape, material, and size of the silicone implant is very important before surgery.</p><p>It is advisable to avoid medication and be in good physical and emotional health to undergo surgery, and even after the implant is in place, care must continue.</p><p>In the first month, for example, it is essential to avoid physical exertion with the arms. In other words, no gym or other strenuous physical exercises.</p><p>It is also important to wear a bra for 24 hours during the first month and avoid sleeping on the stomach, on top of the operated area. If you are a smoker, forget about smoking after the first month of surgery. Ignoring this recommendation affects the surgery\'s healing process and consequently the results.</p><p>It is also not advisable to sunbathe for a period of 2 to 3 months after the procedure. Even after this time, exposure can only be done if the scars are covered with white tape.</p></div>"},"cirurgia-em-ex-obesos":{"title":"Post-Weight Loss Surgery","descr":"If you have experienced dramatic weight loss, whether through diet and exercise or bariatric surgery (obesity surgery), and have reached your ideal weight, then you may be a good candidate for this type of surgery.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Learn more</h2><p>In situations of weight gain or loss in a short period, it is common for skin elasticity to be lost, leading to fat and sagging. To correct this problem, body contouring surgery is one of the most recommended by specialists.</p><p>During the procedure, the surgeon removes the excess skin, thus reshaping the body and \\"lifting\\" the sagging and wrinkled skin.</p><p>Post-obesity surgery is usually associated with other types of surgery, such as liposuction and brachioplasty, for example. This need is assessed according to the patient\'s condition, and regardless of the number of combinations, a medical evaluation before surgery is very important to achieve the desired results.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Before and after the surgery</h2><p>In general, the patient\'s age, the number of areas with sagging skin, and the quality of the skin directly affect the surgery\'s success. As with other procedures, the patient needs to undergo routine tests and prepare for the preoperative period by avoiding medication, alcohol, and smoking.</p><p>After the surgery, it is important to avoid sun exposure for two months, and in addition, hygiene should be done carefully with an antiseptic on the incisions.</p><p>Maintaining a healthy diet and keeping the body hydrated is also very important for preserving the results. Therefore, medical and nutritional follow-up is a good tip for those undergoing body contouring surgery.</p><p>The total recovery time varies depending on the number of surgical combinations for each case.</p></div>"},"cirurgias-combinadas":{"title":"Combined Surgeries","descr":"Associations in plastic surgery have been a widely used resource. The great advantage of these surgical associations is the good result obtained in a single procedure, which brings great savings in time and money for the patient.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Learn more</h2><p>In the realm of plastic surgeries, combined surgeries have grown significantly and attract the attention of patients who want to correct more than one imperfection at the same time.</p><p>One example is post-obesity surgery, which, depending on the sagging and situation, can be combined with liposuction, for example, but the combinations don\'t stop there.</p><p>Many people who undergo liposuction also opt for abdominoplasty, and since both surgeries are performed on the abdomen to reduce localized fat, the combination enhances the results.</p><p>Others insist on combining liposuction with mammoplasty, for example, and there are still those who undergo rhinoplasty with blepharoplasty, and so on.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">How to know if you are a good candidate?</h2><p>The combination of surgeries is a resource that undoubtedly saves patients time and effort. However, it is important to remember that everything must go through medical evaluation, considering factors such as recovery time and the patient\'s physical health conditions.</p><p>It is important to remember that simply wanting without a real need is not a sufficient reason to undergo more than one surgery. In cases where the patient suffers from diseases such as high blood pressure, anemia, and diabetes, for example, combined surgeries are not a good option.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Before and after the surgery</h2><p>In addition to the medical evaluation, the care with routine tests, fasting, and absence of smoking also applies to combined surgeries. In the case of postoperative care, the need varies depending on the type of surgery.</p><p>In general, sun exposure, hygiene, and rest are things that help and interfere with the patient\'s recovery.</p></div>"},"ninfoplastia":{"title":"Labiaplasty","descr":"Labiaplasty, also known as intimate surgery, consists of correcting the hypertrophy (enlargement) of the labia minora in the female genital region. Generally, the removal of fat or excess skin can correct the enlargement.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Learn more</h2><p>Labiaplasty is a surgical procedure aimed at assisting women with hypertrophy in the intimate region.</p><p>And, despite being a surgical procedure that can directly improve the patient\'s well-being and self-esteem, many women are still unaware of it or have doubts about the subject.</p><p>If you are one of those who have doubts about labiaplasty, keep reading this post and find out:</p><br><strong>• What is labiaplasty;</strong><br><br><strong>• Who it is indicated for;</strong><br><br><strong>• What benefits this procedure provides;</strong><br><br><strong>• How labiaplasty works;</strong><br><br><strong>• Who can undergo this type of procedure.</strong><br><br><strong>Check it out!</strong><br><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Labiaplasty: What is it?</h2><p>Labiaplasty is a surgical procedure that corrects imperfections related to the size of the labia minora.</p><p>This structure is located at the entrance of the vagina and is responsible for protecting this region. When the labia minora are hypertrophied, in addition to causing aesthetic discomfort for many women, it can also impair sexual relations, causing pain and discomfort.</p><p>For these and other reasons, many women end up opting for labiaplasty to correct this type of problem.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Who is labiaplasty indicated for?</h2><p>In most cases, this procedure is indicated for women who feel aesthetically uncomfortable with the structure of their labia minora or who experience pain during sexual intercourse caused by this type of alteration. However, there are also clinical cases where this surgery is necessary.</p><p>In some cases, the hypertrophy is so severe that the patient has great difficulty in properly cleaning the vagina. This leads to the accumulation of secretions, which can cause a series of complications, from candidiasis to urinary infections.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">What are the benefits of labiaplasty?</h2><p>Labiaplasty brings a series of benefits to women. Starting with the fact that self-esteem improves significantly, considering that hypertrophy of the labia minora can directly affect the patient\'s emotional state.</p><p>Additionally, the pain during sexual intercourse caused by hypertrophy disappears over time, shortly after the procedure, allowing the woman to have a healthy sexual life without any discomfort.</p><p>Not to mention the hygiene aspect, which becomes easier for the patient who previously had difficulties due to the excess skin in the labia minora region.</p><p>Basically, labiaplasty directly affects the woman\'s well-being, improving her quality of life.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">How does it work?</h2><p>Labiaplasty is performed using anesthesia, and the patient may or may not be sedated. It lasts between forty minutes and an hour.</p><p>During the operation, the surgeon will cut a part of the labia minora to make them smaller. Then, the surgeon will reconstruct them so that the patient does not have any type of scar.</p><p>In fact, after recovery, it is hardly noticeable that the woman underwent labiaplasty.</p><p>One of the great differentiators of this surgical intervention is that the sutures are made with absorbable threads. In other words, they will be naturally absorbed by the body, making it unnecessary for the patient to return to the hospital to remove the stitches.</p><p>In general, the patient is discharged on the same day of the procedure. It is possible to return to daily activities in three days and to have sexual intercourse in three weeks.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Who can undergo labiaplasty?</h2><p>Although it is a relatively simple surgical intervention, it needs to be performed by someone specialized in the area. Otherwise, the patient risks not achieving the desired result and still having scars in her intimate region.</p></div>"}},"BeforeAfter":{"metadata":{"title":"Before and After || Dr. Thomas Benson","description":"See the transformative results of procedures performed by Dr. Thomas Benson. Precise facial rejuvenation, imperceptible scars, and testimonials from satisfied patients with natural and harmonious results."},"h2":"Before and After","atext":"Results that reflect excellence and precision.","p":"Schedule your appointment now with Dr. Thomas Benson."},"BeforeAfterMassonry":{"filters":{"all":"Cases","scars":"Scars","post-surgical":"Post-surgical"},"itemdescr":"Click to see the result"},"Result":{"metadata":{"title":"Result || Dr. Thomas Benson","description":"Excellent results of the procedure performed by Dr. Thomas Benson with before and after."},"i":"Back to the homepage","atext":"Result","p":"The new facial rejuvenation techniques such as Deep Plane and Deep Neck bring several advantages to the results.","h2":"Details","proceduresb":"Procedures:","descriptionb":"Description:","p_2":"No results available here.","ibefore":"Previous","iall":"All results","iafter":"Next"},"portfolios1":{"result1":{"procedures":"Complete Blepharoplasty (Upper / Lower), Deep Plane | MADE, Fat Grafting, CO2 Laser.","descriptionInt":"<div class=\\"container\\"><br/><p>In this case, the patient sought deep facial rejuvenation, focusing on the eye area and facial contour, and Dr. Thomas Benson proposed a personalized combination of procedures to achieve a natural and harmonious result.</p><p>Complete Blepharoplasty, which involved both the upper and lower eyelids, was crucial to correct sagging and excess skin, providing a more open, refreshed, and youthful look. Upper Blepharoplasty softened the heavy lines in the eyelid area, while Lower Blepharoplasty helped reduce fat bags and smooth fine wrinkles, contributing to a more rejuvenated look.</p><p>The combination with Deep Plane Facelift and the MADE (Minimal Access Deep Plane) technique was decisive for deeper rejuvenation, ensuring an effective lift of facial structures without compromising naturalness. Fat grafting was used to reposition volume in areas where fat loss had occurred, providing a younger and balanced contour, restoring facial proportions.</p><p>The use of CO2 Laser complemented the treatment, improving skin texture, smoothing scars and fine lines, and promoting a more uniform and luminous appearance. Each of these procedures worked synergistically, meeting the specific needs of the patient and providing a comprehensive rejuvenation result, with a more open and refreshed look and a younger, firmer, and harmonious face.</p><p>The combination of Blepharoplasty, Deep Plane Facelift, MADE, fat grafting, and CO2 Laser demonstrated Dr. Thomas Benson\'s ability to personalize treatments for each patient, offering exceptional and natural results.</p></div>"},"result2":{"procedures":"Deep Plane | Deep Neck, Fat Grafting, CO2 Laser.","descriptionInt":"<div class=\\"container\\"><br/><p>The patient opted for complete rejuvenation focusing on the face and neck, and Dr. Thomas Benson combined advanced techniques to ensure a natural and harmonious result.</p><p>The Deep Plane Facelift and Deep Neck Lift provided a deep lift, restoring skin firmness and smoothing sagging in both the face and neck. Fat grafting was used to restore volume to areas with fat loss, creating a more balanced and youthful contour.</p><p>The CO2 Laser complemented the treatment, improving skin texture, smoothing wrinkles and spots, and providing a radiant appearance.</p><p>The final result was a transformation that brought natural rejuvenation, with the face and neck visibly firmer and revitalized.</p></div>"},"result3":{"procedures":"Complete Blepharoplasty (Upper / Lower), Deep Plane | Deep Neck, Fat Grafting, Lip Lift.","descriptionInt":"<div class=\\"container\\"><br/><p>The patient sought Dr. Thomas Benson for comprehensive and natural rejuvenation, focusing on the eye area and facial contour. Complete Blepharoplasty (upper and lower) corrected eyelid sagging and reduced fat bags, providing a more rested and youthful look. The Deep Plane Facelift combined with the Deep Neck Lift promoted deep rejuvenation of the face and neck, restoring skin firmness and definition.</p><p>Fat grafting restored volume in areas that lost fullness, and the Lip Lift enhanced the lips, making them more defined and harmonious. The result was a rejuvenated and balanced appearance, with a smoother and natural facial contour.</p></div>"},"result4":{"procedures":"Deep Plane | Deep Neck, Fat Grafting, CO2 Laser, Lip Lift, Brow Lift.","descriptionInt":"<div class=\\"container\\"><br/><p>The combination of procedures provided a complete and harmonious rejuvenation result, with each technique complementing the other precisely and effectively. The Deep Plane Facelift, combined with the Deep Neck Lift, worked on both the face and neck, restoring firmness and definition to areas most affected by sagging. Fat grafting was fundamental in restoring volume to regions that naturally lose this substance with aging, bringing balance and smoothness to the facial contour.</p><p>The CO2 Laser complemented this by improving skin texture, smoothing fine wrinkles and spots, while the Lip Lift provided more natural and proportional lips, enhancing the smile without exaggeration. The brow lift elevated the eye area, providing a more rested and rejuvenated look.</p><p>Each of these procedures was carefully chosen to act on different layers and aspects of facial aging, ensuring a harmonious and natural-looking result without overloading any specific area. The synergistic work between the techniques ensured a deep and balanced transformation, with comprehensive rejuvenation that respected the patient\'s unique characteristics.</p></div>"},"result5":{"procedures":"Deep Plane | Deep Neck, Fat Grafting, CO2 Laser.","descriptionInt":"<div class=\\"container\\"><br/><p>The patient opted for complete rejuvenation focusing on the face and neck, and Dr. Thomas Benson combined advanced techniques to ensure a natural and harmonious result. The Deep Plane Facelift and Deep Neck Lift provided a deep lift, restoring skin firmness and smoothing sagging in both the face and neck.</p><p>Fat grafting was used to restore volume in areas with fat loss, creating a more balanced and youthful contour. The CO2 Laser complemented the treatment, improving skin texture, smoothing wrinkles and spots, and providing a radiant appearance. The final result was a transformation that brought natural rejuvenation, with the face and neck visibly firmer and revitalized.</p></div>"},"result6":{"procedures":"Deep Plane | Deep Neck, Fat Grafting, CO2 Laser, Brow Lift.","descriptionInt":"<div class=\\"container\\"><br/><p>In this case, the patient sought a complete transformation, focusing on rejuvenating the face and neck, and Dr. Thomas Benson developed an integrated treatment plan, combining cutting-edge techniques for a natural and sophisticated result.</p><p>The Deep Plane Facelift was the starting point, providing deep and long-lasting facial rejuvenation, treating sagging and promoting a firmer and more rested appearance. Together, the Deep Neck Lift restored the definition and firmness of the neck area, a region that often reveals signs of aging. Together, these techniques offered comprehensive rejuvenation, with the face and neck becoming more harmonious and proportional.</p><p>Fat grafting was used to restore the volume lost over the years, especially in areas where subcutaneous fat is more susceptible to loss, such as the cheeks and temple area. This ensured a smoother and more youthful contour, as well as providing a more balanced and natural appearance.</p><p>The CO2 Laser complemented this rejuvenation by improving skin texture and treating spots, fine wrinkles, and small imperfections, providing smoother and more radiant skin. Finally, the brow lift was performed to elevate the eyebrow region, providing a more open and rejuvenated look without losing the patient\'s natural expressiveness.</p></div>"}},"RelatedProject10":{"h2":"Other Results","itemdescr":"Click to see the result"},"compTeam":{"role":"Final result","p":"Scars.","span":"Subtle scars with precision and refinement techniques."},"compAbout":{"p":"<p>Doctor of Medicine (PhD) from the prestigious University of São Paulo (USP) in Brazil, and Doctor of Medicine (PhD) from the University of Hamburg (UKE – Universitätsklinik Eppendorf Hamburg) in Germany, Dr. Thomas built his career at the two most respected institutions in the medical field.<br/><br/>He is also the only plastic surgeon in Brazil with a specialist title from the European Board of Plastic Surgery (EBOPRAS), after passing his specialist exam in Brussels, Belgium, and Bern, Switzerland, to obtain his certificate. Dr. Thomas Benson holds specialist titles in Brazil, being a full member of SBCP and also recognized by the German government.<br/><br/>His training includes residency in General Surgery and Plastic Surgery at the Hospital das Clínicas of USP, postgraduate studies in microsurgery at USP, one of the largest reference centers in facial and head and neck reconstructions in Latin America, completed a medical residency at Bogenhausen Hospital in Munich, Germany, where he was responsible for the preceptorship of training that year, served as a plastic surgeon at Bogenhausen Hospital, and later specialized and trained with several renowned surgeons in Brazil and the USA, where he honed his skills in facial surgery techniques, including the Deep Plane Facelift.<br/><br/>Dr. Thomas is a member of the medical staff at Albert Einstein Israeli Hospital, Sírio Libanês Hospital, and Moriah Hospital, and today operates every day from Monday to Saturday, performing seven surgeries per week at Brazil\'s only 6-star hospital, Vila Nova Star (SP), a top reference in highly secure and technological infrastructure.<br/><br/> </p>"},"Faq":{"faqs":{"1":{"question":"Doctor of Medicine PhD from the university in SP","answer":"Certified by the European Board of Plastic Surgery Double PhD from the University of São Paulo, Brazil, and the University of Hamburg, Germany."},"2":{"question":"Doctor of Medicine PhD from the university in Hamburg","answer":"Certified by the German Board and the University of Hamburg, Germany."},"3":{"question":"Plastic surgeon specialist in Europe by the European Board","answer":"Currently the only plastic surgeon in Brazil with a Specialist Title from the European Board of Plastic Surgery."},"4":{"question":"Plastic surgeon specialist by the German Government","answer":"Specialist Member of the German Society of Plastic Surgery."},"5":{"question":"Plastic surgeon specialist by the Brazilian Society of Plastic Surgery Full member of the Brazilian Society of Plastic Surgery","answer":"Specialist Member of the Brazilian Society of Plastic Surgery."},"6":{"question":"American Academy of Facial Plastic and Reconstructive Surgery","answer":"Specialist Member of the American Society of Plastic Surgery."},"7":{"question":"American Society of Plastic Surgery","answer":"Member of the American Society of Plastic Surgery."},"8":{"question":"Member of the European Society of Plastic","answer":"Member of the European Society of Plastic, Reconstructive and Aesthetic Surgery (ESPRAS)."},"9":{"question":"Member of the International Confederation for Plastic","answer":"Member of the International Confederation for Plastic, Reconstructive and Aesthetic Surgery (IPRAS)."},"10":{"question":"Member of the Society","answer":"Member of the German Society of Surgeons (DGCH)."},"11":{"question":"Specialist Member","answer":"Specialist Member of the European Board of Plastic Surgery (EBOPRAS)."},"12":{"question":"Member of the Association","answer":"Member of the Association of Former Students of Plastic Surgery HC-FMUSP."},"13":{"question":"Member of the Association","answer":"Member of the Professional Association of Doctors of Germany (Landesärztekammer Bayern)."},"14":{"question":"Member of the Association","answer":"Member of the Professional Association of Doctors of Munich (Bezirksärztekammer München)."},"15":{"question":"Medical Specialty","answer":"Aesthetic Plastic Surgery with a focus on Facial Surgeries. Today he is one of the pioneers in Brazil in the innovative facial rejuvenation technique Deep Plane Facelift."},"16":{"question":"Detailed and safe plastic surgery","answer":"After graduating in Brazil as a plastic surgeon, he completed another medical residency in plastic surgery at the Bogenhausen Hospital in Munich to obtain the title of Specialist in Plastic and Aesthetic Surgery by the German Government."},"17":{"question":"Best Seller Author","answer":"\'The Beauty of the Face\'. The essential information that every patient should know to enhance natural features and rejuvenate safely."}}},"Serviceabout":{"h2":"Leadership in Brazil","atext":"Top safety.","p":"Dr. Thomas Benson is the only plastic surgeon in Brazil with a PhD in Germany and Brazil and a specialist title from the European Board of Plastic Surgery.","item1":"We operate at the only 6-star hospital in Brazil.","item2":"Best technologies.","item3":"Concierge with individualized care.","item4":"Post-surgical protocols.","servtitle1":"Hospital Vila Nova Star","servp1":"Dr. Thomas is also a member of the medical staff at other major hospitals, such as Albert Einstein Israeli Hospital and Sírio-Libanês Hospital.","servtitle2":"Cutting-edge technology","servp2":"We combine the best available technologies with the expertise of our team, ensuring safe, precise procedures and superior results.","servtitle3":"Exclusive service","servp3":"Our concierge team offers a premium service, fully dedicated to your needs. From organizing appointments and surgeries to providing support with accommodation, transportation, and other requests, we ensure a smooth and comfortable experience.","servtitle4":"Follow-up and recovery with excellence","servp4":"We follow rigorous and exclusive post-surgical protocols, developed especially for each patient. With attentive follow-up by our team, our commitment is to ensure a quick and safe recovery."},"Portfolio":{"h2":"Before and After","atext":"Excellent results in Deep Plane Facelift.","filters":{"all":"Cases","scars":"Scars","postSurgical":"Post-Surgical"},"portfolios1":{"description":"Click to see the result"}},"VideoContainer":{"p":"A special message for you!","videodesc":"Check out these two videos.","videoContainersrc":{"descr":"Click on the link to Instagram."}},"VideoTestimonials":{"p":"Patient testimonials.","desc":"Check out some feedback from our dear patients<br /> about pre and post surgery.","videodesc":"Click to watch the testimonial"},"Service":{"h2":"Leadership in Brazil","atext":"Top safety.","item1":"Experience and exclusivity.","item2":"Proven technical skill.","item3":"Daily improvement.","item4":"Detailed safety protocols.","servtitle1":"International recognition","servp1":"<p>PhD in Brazil and Germany by the University of Hamburg, being the only Brazilian recognized by the European Council of Plastic Surgery and the German and American Society of Plastic Surgery.<br /><br /> Dr. Thomas Benson is truly exclusive and choosing him means opting for a professional whose international prestige attests to his competence and distinction in the field of facial plastic surgeries.</p>","servtitle2":"+ 5,000 cases","servp2":"<p>Dr. Thomas has been working in private practice since 2009, today performing an average of 350 procedures per year. <br /><br /> Specialist and Plastic Surgeon in Germany and Europe and PhD in both countries. With a solid experience and proven technical skill in more than 5,000 successful cases, Dr. Thomas Benson is the reliable choice for exceptional facial transformations.</p>","servtitle3":"Excellence and continuous improvement","servp3":"<p>Committed to excellence, Dr. Thomas not only has extensive experience, but also seeks constant improvement, having a daily surgical schedule in the best hospitals in the country with the latest innovations and techniques. <br /><br /> He also participates in various congresses in Brazil and worldwide with the biggest names in plastic surgery, as a participant and speaker transmitting his technical and practical knowledge gained over 15 years.</p>","servtitle4":"Exclusive structure and prestige","servp4":"<p>We operate in the best hospitals in Brazil including and enjoying the most innovative and technological surgical centers in the country. <br /><br /> Dr. Thomas Benson is truly exclusive and choosing him means opting for a professional whose international prestige attests to his competence and distinction in the field of facial plastic surgeries.</p>"},"Portfolio2":{"h3":"Reference in the entire press.","PressItems":{"1":{"title":"Pioneering in Brazil: Dr. Thomas Benson has been a reference in the press since 2021.","article":"<p>A specialist in facial surgery, Dr. Thomas Benson, graduated from the University of Hamburg, is now the only Brazilian with a specialist title from the European Board of Plastic Surgery of the European Council of Plastic Surgery. On that occasion, the specialization was done in Germany and other European countries and validated in Brazil.</p><p>The surgeon\'s German medical diploma had already been recognized by the University of São Paulo (USP) and, today, he also interacts with plastic surgery in other ways. Currently, Thomas even participates as a volunteer in breast reconstructions carried out at Albert Einstein Hospital.</p><p>Click the button below to continue reading this article on R7.</p><br/>"},"2":{"title":"Highlighted in Brazil with a live series on Record TV in 2021 in the program \'The Hospital\'.","article":"<p>With episodes in a reality show format, <em>The Hospital</em> captures the behind-the-scenes of the Moriah Hospital, one of the largest in Latin America and renowned for its advanced procedures.</p><p>The documentary series has caught the public\'s attention by highlighting the dedication, vulnerabilities, losses, and achievements of healthcare professionals.</p><p>Click the button below to continue reading this article on R7.</p><br/>"},"3":{"title":"Deep Plane Facelift: Dr. Thomas Benson is featured on Domingo Espetacular.","article":"<p>Facial harmonization procedures have never been as prominent as they are today. Among other reasons, social media and video calls, driven by remote work during the pandemic, have led to a 13.9% increase in facial aesthetic interventions between the biennia 2018-2019 and 2020-2021, according to the International Society of Aesthetic Plastic Surgery (ISAPS).</p><p>To discuss the topic, \'Domingo Espetacular\' on TV Record interviewed Dr. Thomas Benson. In a program that aired on Sunday night (20), the plastic surgeon explained how the \'deep plane facelift\', the most advanced facial surgery in the world, works and how it has become a trend in the United States.</p><p>Click the button below to continue reading this article on IstoÉ.</p><br/>"}},"viewArticle":"View article"},"Promo":{"h2":"Dr. Thomas launched <em>A BEST SELLER.</em>","featureItems2":{"1":{"title":"Best seller by VEJA","description":"The essential information every patient should know to enhance natural features and rejuvenate safely."},"2":{"title":"Featured on R7","description":"Plastic surgeon Thomas Benson has his European title recognized in Brazil."},"3":{"title":"Article in ISTOÉ","description":"Dr. Thomas Benson explains about the plastic surgery that is a trend in the USA."},"4":{"title":"Featured on Terra","description":"Dr. Thomas Benson explains more details about the Deep Plane Facelift technique."}}},"Faq2":{"faqDataMain":{"1":{"question":"How do the consultations work?","answer":"<p>Consultations at Dr. Thomas Benson\'s clinic are designed to offer an exclusive and sophisticated experience, reflecting excellence and pioneering in facial plastic surgery in Brazil and around the world.</p><p>Patients can choose between in-person consultations, at a clinic located in an upscale neighborhood in São Paulo, or online consultations, which allow for an initial appointment with the same attention and quality, especially for patients from other cities or countries.</p><p>During the consultation, a comprehensive and personalized analysis is conducted to identify the patient\'s needs and assess the feasibility of procedures, such as the Deep Plane Facelift, for which Dr. Thomas Benson is a pioneer in Brazil.</p><p>Upon arriving at the clinic, patients are welcomed by an exclusive concierge service, ensuring comfort and convenience from the moment they enter. All appointments are scheduled to avoid waiting times and guarantee privacy and respect for each patient\'s time.</p><p>The clinic provides a luxurious and sophisticated experience, aligned with the highest international standards of care. Located in the heart of an upscale neighborhood in São Paulo, the space is designed to offer not only comfort but also an environment that reflects the trust and excellence associated with Dr. Thomas Benson\'s name.</p><p>Whether in-person or online, each consultation is conducted with a commitment to offering a unique and transformative journey, reinforcing the humanized care and high standards that define Dr. Thomas Benson\'s work.</p>"},"2":{"question":"Does Dr. Thomas accept insurance?","answer":"<p>No, Dr. Thomas Benson does not accept insurance. His care is focused on offering an exclusive and personalized experience, prioritizing the highest standard of quality and exceptional results. Each consultation and procedure is individually planned, with advanced techniques performed in a 6-star hospital, ensuring maximum safety and sophistication.</p><p>For information about prices and appointments, please contact the clinic team, who will be available to assist and provide a unique and transformative journey.</p>"},"3":{"question":"What procedures are performed by the doctor?","answer":"<p>Dr. Thomas Benson is widely recognized as a reference in facial surgeries, with a special focus on the Deep Plane Facelift, a technique that offers natural and long-lasting results for facial rejuvenation. Additionally, he performs procedures such as neck lifts, blepharoplasty (eyelid surgery), rhinoplasty, and other interventions that harmonize and enhance facial features with technical precision and attention to detail.</p><p>Although facial surgeries are his specialty and priority, Dr. Thomas Benson also has extensive experience in other areas of plastic surgery. He performs body procedures such as abdominoplasty, liposuction, and buttock augmentation, as well as breast surgeries and body contouring surgeries for patients seeking to redefine their proportions and improve their self-esteem.</p><p>His differential lies in the combination of a solid international education and high-volume daily practice, with 7 surgeries performed weekly throughout the year. This constant experience gives him exceptional technical mastery not only in facial surgeries but also in other areas of plastic surgery.</p><p>Regardless of the type of procedure, Dr. Thomas Benson guarantees a personalized approach, aligning realistic expectations with results that enhance each patient\'s natural beauty. Schedule your consultation to discover how he can transform your vision of beauty with excellence and exclusivity.</p>"},"4":{"question":"What to expect from the results of a facial surgery?","answer":"<p>The results of facial surgery with Dr. Thomas Benson are carefully planned to offer natural and harmonious rejuvenation. Dr. Thomas Benson\'s internationally recognized technique prioritizes the preservation of each patient\'s unique identity and expressions, ensuring that the transformation is subtle and balanced, without that artificial or \'stretched\' look.</p><p>Safety is one of the pillars of Dr. Thomas Benson\'s work. All surgeries are performed in a 6-star hospital, considered the most advanced in the country, following strict international standard protocols. This care ensures not only a safe procedure but also peace of mind throughout the entire process.</p><p>Another differential is the care with scars. Dr. Thomas Benson\'s meticulous approach and refined technique ensure that incisions are made in strategic locations and treated in a way that makes them virtually imperceptible. The goal is for the results to be so natural that even the signs of surgery are almost invisible.</p><p>After the procedure, patients benefit from excellent post-operative protocols, developed for a quick and comfortable recovery. These include personalized follow-up, detailed guidance, and the use of advanced technologies to accelerate healing and minimize swelling and discomfort.</p>"}}},"Benefits":{"h2":"Main benefits","h3":"Why choose Dr. Thomas?","featureItems":{"1":{"title":"Natural and real results","description":"We reposition the layers, generating more effective and more beautiful results, enhancing the quality of the skin."},"2":{"title":"Fine and imperceptible scars","description":"Repositioning and removing excess skin, combined with post-surgical follow-up, make the scars imperceptible."},"3":{"title":"Post-surgical follow-up","description":"We have a specialized team and cutting-edge technology to provide comprehensive post-surgical follow-up, taking care of the entire process from start to finish."}}},"Testimonials":{"h2":"Over 5,700 patients have trusted in Dr. Thomas\'s excellence and protocols.","testimonials":{"0":{"quote":"I had my Facelift with Dr. Thomas a year ago, and I am very satisfied with the result. It looks so natural that people I know ask me what I do to not age! Having facial surgery is a very difficult decision because if something goes wrong, there is no way to hide it. That being said, I can confirm that Dr. Thomas will provide you with a natural and perfect result. Thank you, Dr. Thomas! Your hands are truly blessed! Your team is also wonderful!","role":"Patient"},"1":{"quote":"It\'s been one year since my surgery, and I can only thank Dr. Thomas Benson. The result is still perfect, and he is undoubtedly one of the best surgeons in Brazil and the world. Excellent work.","role":"Patient"},"2":{"quote":"Always very attentive, extremely professional, and careful to leave the patient without doubts and build the utmost confidence in his technical knowledge and the human and personalized treatment of the patient. Excellent professional.","role":"Patient"}}},"Contact":{"h2":"Contact","atext":"Take the first step. Come and experience it!","h4":"Contact us","consulth4":"Office in São Paulo"},"Footer1":{"p1":"Dr. Thomas Benson, one of the pioneers in Brazil in the innovative Deep Plane Facelift technique.","h3":"Pages","navigationLinks":{"0":{"text":"About"},"1":{"text":"Team"},"2":{"text":"Blog"},"3":{"text":"Press"},"4":{"text":"Patients Abroad"},"5":{"text":"Surgeries"},"6":{"text":"Before & After"}},"h3_2":"Socials","p2":"This website is informational and educational in nature and adheres to the principles of Resolution No. 1,974/2011 of the Federal Council of Medicine (CFM) and the code of conduct for medicine and health. Patients should never use its content for self-diagnosis or self-treatment. According to the recommendation of the Federal Council of Medicine, in case of doubt, a doctor should always be consulted.","b1":"All rights reserved","b2":"Responsible technician: Dr. Thomas Benson CRM. 119.278 – RQE 29279."}}');

