"use strict";
module.exports = /*#__PURE__*/JSON.parse('{"ScheduleButton":{"textbtn":"Agendar consulta"},"Header1Multipage":{"span":"Marque a sua consulta"},"menuItems2":{"mainMenu":{"home":"Início","drThomas":"Dr. Thomas","press":"Imprensa","international":"Pacientes no Exterior","surgeries":"Cirurgias","beforeAfter":"Antes e Depois"},"subMenu":{"home":"Início","about":"Sobre","team":"Equipe","blog":"Blog","press":"Imprensa","international":"Pacientes no Exterior","surgeries":"Cirurgias","beforeAfter":"Antes e Depois"}},"Home":{"metadata":{"title":"Dr. Thomas Benson, PhD - Cirurgião Plástico","description":"Conheça o Dr. Thomas Benson, referência em cirurgia plástica facial e especialista em Deep Plane Facelift na América Latina. Excelência em técnicas inovadoras para resultados naturais, segurança e exclusividade."},"title":"Dr. Thomas Benson, PhD - Cirurgião Plástico","description":"Conheça o Dr. Thomas Benson, referência em cirurgia plástica facial e especialista em Deep Plane Facelift na América Latina. Excelência em técnicas inovadoras para resultados naturais, segurança e exclusividade.","h1":"Especialista e referência em cirurgias faciais.","pdesc":"Há 15 anos atuando com os mais altos padrões de qualidade e excelência no rejuvenescimento facial.","videobtn":"Clique aqui e veja o vídeo!","scrolld":"Rolar para baixo","abouth2":"Uma carreira marcada pela excelência.","aboutp":"Doutor em Medicina (PhD) pelas prestigiadas Universidade de São Paulo (USP), no Brasil, e Doutor em Medicina (PhD) pela Universidade de Hamburgo (UKE – Universitätsklinik Eppendorf Hamburg) na Alemanha, o Dr. Thomas construiu sua carreira nas duas instituições mais respeitadas na área médica.<br/><br/> Ele também é o único cirurgião plástico no Brasil com título de especialista pelo European Board of Plastic Surgery (EBOPRAS),após ter feito sua prova de especialista em Bruxelas, Bélgica e em Bern, Suíça para obter seu certificado. Dr. Thomas Benson possui títulos de especialista no Brasil sendo membro titular da SBCP e também pelo governo Alemão.<br/><br/> Sua formação inclui residência em Cirurgia Geral e Cirurgia Plástica no Hospital das Clínicas da USP, pós graduação em microcirurgia na USP, um dos maiores centros de referência em reconstruções faciais e de cabeça e pescoço da América Latina, fez residência médica no Hospital Bogenhausen, em Munique, Alemanha, onde foi responsável pela preceptoria da formação naquele ano, onde atuou como cirurgião plástico no Hospital Bogenhausen, após esse período se especializou e acompanhou vários cirurgiões renomados no Brasil e nos EUA onde se aprimorou nas técnicas de cirurgia de face, inclusive o Deep Plane Facelift.<br/><br/> O Dr. Thomas é membro do corpo clínico do hospital Israelita Albert Einstein, hospital Sírio Libanês, hospital Moriah, hoje, opera todos os dias de segunda a sábado, sendo sete cirurgias por semana no único hospital 6 estrelas do Brasil, o Vila Nova Star (SP), referência máxima em infraestrutura altamente segura e tecnológica.<br/><br/>","clinicah2":"Consultório de cirurgias plásticas em São Paulo.","clinicap":"O Consultório Médico Particular do Dr. Thomas Benson está localizado ao lado do Parque Ibirapuera na Av. Antônio Joaquim de Moura Andrade, no bairro nobre da Vila Nova Conceição em São Paulo, um ambiente luxuoso e confortável com total segurança.","features":{"excellence":"Estrutura de excelência","technology":"Tecnologia de ponta","care":"Cuidados individualizados","safety":"Segurança e equipe multidisciplinar"},"ct1h2":"Somos uma das poucas equipes exclusivas que operam face todos os dias.","ct1p":"A excelência vem através da repetição prática diária.","numberItems":{"cases":"Casos de face por semana.","experience":"Anos de experiência.","countries":"Países buscam a excelência do Dr. Thomas no Brasil.","surgeries":"Cirurgias realizadas."},"hosph2":"Dr. Thomas realiza cirurgias todos os dias no único hospital 6 estrelas do país.","hospp":"Dr. Thomas também é membro do corpo clínico de outros grandes hospitais, como: Hospital Israelita Albert Einstein e Hospital Sírio-Libanês.","features2":{"1":{"text":"Melhores tecnologias."},"2":{"text":"Concierge com cuidados individuais."},"3":{"text":"Protocolos pós-cirúrgicos."},"4":{"text":"Segurança e exclusividade."}},"faqh3":"Dúvidas que alguns pacientes podem ter.","sectionp":"Pioneirismo, exclusividade e uma carreira marcada pela excelência e dedicação. O Dr. Thomas Benson é um dos maiores especialistas em rejuvenescimento facial."},"About":{"metadata":{"title":"Sobre || Dr. Thomas Benson","description":"Saiba mais sobre o Dr. Thomas Benson, PhD em cirurgia plástica, único brasileiro reconhecido pelo Conselho Europeu de Cirurgia Plástica e pela Sociedade Alemã de Cirurgia Plástica. Autor do best-seller \'A Beleza da Face\' e referência em técnicas avançadas como o Deep Plane Facelift."},"h2_1":"Sobre","p1":"Especialista em cirurgias faciais, é o único brasileiro com título de especialização do Conselho Europeu de Cirurgia Plástica e da Sociedade Alemã de Cirurgia Plástica.","h2_2":"Nossa História","atext1":"O caminho da excelência.","h2_3":"Uma carreira marcada pela excelência.","ct1h2":"Somos uma das poucas equipes exclusivas que operam face todos os dias.","ct1p":"A excelência vem através da repetição prática diária.","p2":"Pioneirismo, exclusividade e uma carreira marcada pela excelência e dedicação. O Dr. Thomas Benson é um dos maiores especialistas em rejuvenescimento facial."},"Team":{"metadata":{"title":"Equipe || Dr. Thomas Benson","description":"Conheça a equipe de especialistas liderada pelo Dr. Thomas Benson e descubra a infraestrutura de excelência da clínica, focada em segurança, conforto e resultados de alto padrão em cirurgia plástica facial."},"h2":"Equipe","atext":"Conheça a nossa equipe de especialistas.","squadMembers":{"0":{"role":"Cirurgião Plástico"},"1":{"role":"Gerente"},"2":{"role":"Cirurgião Plástico"},"3":{"role":"Cirurgião Plástico"},"4":{"role":"Cirurgião Plástico"},"5":{"role":"Cirurgiã Plástica"},"6":{"role":"Enfermagem"},"7":{"role":"Enfermagem"},"8":{"role":"Enfermagem"},"9":{"role":"Administração"},"10":{"role":"Concierge"}},"div":"Segurança, conforto e tecnologia para cada paciente.","p":"Segurança e conforto dos pacientes são a prioridade: atendimento premium humanizado e infraestrutura equipada com uma das tecnologias mais avançadas para cirurgia plástica e recuperação, além de toda a comodidade para pacientes de todo o Brasil.","h2_2":"Nossos pacientes dizem","span":"Relatos de pacientes que encontraram excelência, cuidado e resultados excepcionais.","div_2":"Cirurgias realizadas nos melhores hospitais do país.","p_2":"O Dr. Benson realiza suas cirurgias em hospitais que contam com uma equipe de profissionais altamente qualificados e equipamentos de última geração. Isso garante que seus pacientes recebam o melhor atendimento possível, desde o pré-operatório até o pós-operatório.","h3":"Dúvidas que alguns pacientes podem ter.","p_3":"Pioneirismo, exclusividade e uma carreira marcada pela excelência e dedicação. O Dr. Thomas Benson é um dos maiores especialistas em rejuvenescimento facial."},"teamTestimonials":{"role":"Paciente","testimonials3":{"1":{"text":"Dr Thomas é um profissional incrível, amei meu procedimento. Ele explicou com muito cuidado todo meu procedimento, tirou as dúvidas, a consulta foi muito esclarecedora e detalhada. Equipe toda achei maravilhosa e cuidadosa. Recomendo muito."},"2":{"text":"Gratidão é a palavra! Dr. Thomas um profissional excelente e muito cuidadoso com seus pacientes. Em todos os momentos me passou segurança, o resultado trouxe de volta a minha auto estima e a minha identidade. À toda a equipe obrigado, de coração. Deus abençoe a todos vocês."},"3":{"text":"Superou a minha expectativa. O meu sentimento é de gratidão a todos que cuidaram de mim com tanto carinho e atenção, desde a primeira consulta até o acompanhamento final. Meus amigos e familiares ficaram impressionados com o resultado é só ouço elogios."},"4":{"text":"Desde a 1a consulta até as sessões pós cirurgia, todo o caminho foi cercado de cuidados e atenções da parte dele e de sua equipe excepcional. Tudoooo transcorreu no maior clima de tranquilidade, segurança e confiança, não podia ter sido melhor."},"5":{"text":"Super satisfeita. O Doutor Benson devolveu minha autoestima . Fiz uma cirurgia plástica facial e foi a melhor escolha que fiz . Ótimo trabalho, funcionários super atenciosos e carinhosos . Uma equipe excelente .E o Doutor Benson é incrível ! Só tenho a agradecer por tudo . EU AMEI"},"6":{"text":"Só tenho a agradecer pelo profissional maravilhoso e pela equipe muito bem treinada, tive todo o suporte desde o dia da consulta até os retornos pós operatório, médico humano, honesto e muito sensato. Mudou a minha autoestima e minha vida, eterna gratidão a todos."}}},"Brands":{"h2":"Certificações Nacionais e Internacionais."},"pagePress":{"metadata":{"title":"Imprensa || Dr. Thomas Benson","description":"Veja as aparições do Dr. Thomas Benson na mídia como referência em cirurgia plástica facial. Destaque em jornais, revistas, programas de TV e séries documentais, incluindo \'O Hospital\', da Record."},"h2":"Imprensa","atext":"Dr. Thomas Benson na mídia: referência em cirurgia plástica.","p":"Agende agora mesmo seu horário com o <br/>Dr. Thomas Benson."},"Gallery2":{"pressItems":{"1":{"title":"Pioneirismo no Brasil: Dr. Thomas Benson é referência na imprensa desde 2021."},"2":{"title":"Destaque no Brasil com série ao vivo na Record em 2021 no programa \'O Hospital\'."},"3":{"title":"Deep Plane Facelift: Dr. Thomas Benson é destaque no Domingo Espetacular."},"4":{"title":"Celebridades fazem procedimentos e são atacados nas redes sociais."},"5":{"title":"Conselho Federal de Medicina autoriza a divulgação de fotos de \'antes e depois\' de procedimentos."},"6":{"title":"Novas regras para publicidade médica."},"7":{"title":"Procedimentos estéticos no rosto ficam em alta na pandemia."},"8":{"title":"PORTAL ETC - Dr Thomas Benson: o melhor cirurgião plástico da face da América Latina."},"9":{"title":"Rinoplastia - Domingo Espetacular."},"10":{"title":"Dr. Thomas Benson - Saúde: Lipoenxertia - Programa Mulheres."},"11":{"title":"321 - Thomas Benson & Rafael de La Lastra."},"12":{"title":"Plástica com know-how internacional em Alphaville - Revista Vero."}}},"Blog":{"atext":"Fique por dentro dos principais temas sobre cirúrgia plástica!"},"BlogClient":{"placeholder":"Buscar..."},"BlogSlug":{"i":"Voltar para a página do blog"},"BlogWidget2":{"placeholder":"Buscar...","h3":"Últimas postagens","span":"Postado em","li":"Nenhum resultado encontrado.","h3_2":"Categorias","categories":{"abdominoplastia":"Abdominoplastia","blefaroplastia":"Blefaroplastia","braquioplastia":"Braquioplastia","cicatriz":"Cicatriz","lipoaspiração":"Lipoaspiração","mamoplastia":"Mamoplastia","rinoplastia":"Rinoplastia"}},"PressNewsPage":{"i":"Voltar para a página de imprensa","a":"Leia o artigo completo","p":"Agende agora mesmo seu horário com o Dr. Thomas Benson.","PressItems":{"1":{"title":"Pioneirismo no Brasil: Dr. Thomas Benson é referência na imprensa desde 2021.","article":"<p>Especialista em cirurgia da face, o médico Thomas Benson, formado pela Universidade de Hamburgo, é agora o único brasileiro com título de especialista pelo European Board of Plastic Surgery, do Conselho Europeu de Cirurgia Plástica. Na ocasião, a especialização foi feita na Alemanha e outros países da Europa e validada no Brasil.</p><p>O diploma médico alemão do cirurgião já havia sido reconhecido pela Universidade de São Paulo (USP) e, hoje, ele também interage com a cirurgia plástica de outra forma. Atualmente, Thomas participa até como voluntário em reconstruções mamárias que são realizadas no Albert Einstein.</p><p>Clique no botão abaixo para continuar lendo esta matéria no R7.</p><br/>"},"2":{"title":"Destaque no Brasil com série ao vivo na Record em 2021 no programa \'O Hospital\'.","article":"<p>Com episódios em formato de reality, <em>O Hospital</em> registra os bastidores do Hospital Moriah, um dos maiores da América Latina e referência por seus procedimentos avançados.</p><p>A série documental tem chamado a atenção do público ao destacar a dedicação, as fragilidades, perdas e conquistas dos profissionais da área da saúde.</p><p>Clique no botão abaixo para continuar lendo esta matéria no R7.</p><br/>"},"3":{"title":"Deep Plane Facelift: Dr. Thomas Benson é destaque no Domingo Espetacular.","article":"<p>Procedimentos de harmonização facial nunca estiveram tão em evidência como na atualidade. Entre outras razões, as redes sociais e as chamadas de vídeo, impulsionadas pelo trabalho remoto durante a pandemia, fizeram com que intervenções estéticas no rosto crescessem 13,9% na comparação entre os biênios 2018-2019 e 2020-2021, de acordo com a Sociedade Internacional de Cirurgia Plástica e Estética (ISAPS).</p><p>Para falar do assunto, o ‘Domingo Espetacular’, da TV Record, entrevistou o Dr. Thomas Benson. Em programa que foi ao ar na noite desse domingo (20), o cirurgião plástico explicou como funciona o ‘deep plane facelift’, cirurgia facial mais avançada do mundo, e que é febre nos Estados Unidos.</p><p>Clique no botão abaixo para continuar lendo esta matéria na IstoÉ.</p><br/>"},"4":{"title":"Celebridades fazem procedimentos e são atacados nas redes sociais.","article":""},"5":{"title":"Conselho Federal de Medicina autoriza a divulgação de fotos de \'antes e depois\' de procedimentos.","article":""},"6":{"title":"Novas regras para publicidade médica.","article":""},"7":{"title":"Procedimentos estéticos no rosto ficam em alta na pandemia.","article":""},"8":{"title":"PORTAL ETC - Dr Thomas Benson: o melhor cirurgião plástico da face da América Latina.","article":"<p>O cirurgião plástico paulistano, Dr Thomas Benson, é especialista em face. Ele é o único brasileiro com título de especialização do Conselho Europeu de Cirurgia Plástica e da Sociedade Alemã de Cirurgia Plástica. Além disso, também tem títulos de especialização pelas Sociedades Brasileira e Americana de Cirurgia Plástica.</p><p>Ele acaba de receber o prêmio de Profissional de Qualidade, na categoria ‘Cirurgião Plástico’ 2020. Essa premiação reconhece os profissionais que se destacaram em sua área de atuação no último ano. Dr Benson é formado pela USP e pela Universidade de Hamburgo (Alemanha), e faz sucesso na internet com mais de 100 mil seguidores no Instagram.</p><p>Ele é tão talentoso que sua agenda está completamente lotada. Mas todos os sonhos, e trabalho, só são possíveis, por conta do apoio que recebe da família. Para ele, sua esposa e sua filha, são a base de tudo na vida.</p><br/>"},"9":{"title":"Rinoplastia - Domingo Espetacular.","article":""},"10":{"title":"Dr. Thomas Benson - Saúde: Lipoenxertia - Programa Mulheres.","article":""},"11":{"title":"321 - Thomas Benson & Rafael de La Lastra.","article":""},"12":{"title":"Plástica com know-how internacional em Alphaville - Revista Vero.","article":"<p>Às vezes, a gente até esquece. Mas, muitas vezes, os benefícios da cirurgia plástica estão diretamente ligados à qualidade de vida.</p><p>\'O que me move é ver o retorno do meu trabalho no sorriso de cada paciente. Elas voltam ao consultório mais felizes e com a autoestima renovada\', relata o cirurgião plástico Thomas Benson, de 39 anos, especialista nessa técnica de melhorar a vida das pessoas por meio dos bisturis.</p><p>O jovem médico, que é atualmente o único no Brasil com título de especialista pelo European Board of Plastic Surgery (Conselho Europeu de Cirurgia Plástica), chegou a Alphaville pelo caminho de maior credibilidade possível: indicações. \'Eu atendia mais na região de São Paulo, mas já tinha pacientes no bairro. Elas começaram a me indicar para outras, que nem sempre conseguiam se deslocar até minha clínica na capital\', conta.</p><p>Foi quando o cirurgião, nascido no Brasil e crescido na Alemanha, decidiu abrir alguns dias na agenda para atender por aqui. Mas não pense que ele apenas faz um pré-atendimento. Ele traz a equipe toda: \'Em parceria com a Dra. Karina Nunes, levo minha equipe para a Innovare Clinic, que tem uma infraestrutura multidisciplinar necessária para as consultas\', explica.</p><br/>"}}},"patientsAbroad":{"metadata":{"title":"Pacientes no Exterior || Dr. Thomas Benson","description":"Descubra como pacientes de todo o mundo escolhem o Dr. Thomas Benson pela excelência em cirurgia plástica facial. Oferecemos concierge personalizado, hospedagem e uma experiência cirúrgica completa em São Paulo."},"h2":"Pacientes no Exterior","atext":"Fenômeno global de turismo médico.","p1":"Pacientes de diversos lugares do mundo viajam para realizar procedimentos com o Dr. Thomas.","p2":"Devido a sua excelência técnica, resultados excepcionais e compreensão das necessidades do paciente, pessoas de diversos lugares do mundo inteiro optam por viajarem até São Paulo para ter o procedimento realizado pelo Dr. Thomas.","div":"Nosso concierge cuidará de toda a sua experiência de ponta a ponta.","p3":"Nosso concierge te ajudará na hospedagem com a localização privilegiada e com todo o transporte desde a sua chegada até a sua liberação do pós cirúrgico, proporcionando uma experiência completa para que você se sinta em casa.","h3":"Experiência cirúrgica global:","p4":"Explore a impactante experiência cirúrgica no Brasil com o Dr. Thomas Benson, PHD no Brasil e na Alemanha. Pacientes de todo o mundo buscam a excelência na prática do Dr. Thomas.","progressData":{"0":{"label":"Brazil (procedimentos cirúrgicos realizados) 70"},"1":{"label":"USA (procedimentos cirúrgicos realizados) 20"},"2":{"label":"Europe (procedimentos cirúrgicos realizados) 10"}},"p5":"Agende agora mesmo seu horário com o Dr. Thomas Benson."},"Surgeries":{"metadata":{"title":"Cirurgias || Dr. Thomas Benson","description":"Conheça as cirurgias realizadas pelo Dr. Thomas Benson, incluindo técnicas avançadas, cuidados pré e pós-operatórios, e procedimentos personalizados para resultados naturais, seguros, com cicatrizes finas e imperceptíveis."},"h2":"Cirurgias","atext":"Conheça as cirurgias realizadas pelo Dr. Thomas Benson.","p":"Agende agora mesmo seu horário com o Dr. Thomas Benson."},"SurgeriesPortfolio":{"filters":{"all":"Todas","facials":"Cirurgias Faciais","others":"Outras Cirurgias"}},"surgeriesItems":{"1":{"title":"Deep Plane Facelift","descr":"A cirurgia de Lifting Facial Deep Plane é considerada uma das técnicas cirúrgicas mais avançadas e inovadoras para rejuvenescimento facial, combinando resultados mais naturais e duradouros com o benefício de não possuir praticamente nenhuma cicatriz visível."},"2":{"title":"Rinoplastia","descr":"Indicada para quem quer modelar o tamanho e a proporção do nariz, a rinoplastia é uma das cirurgias mais procuradas para finalidades estéticas. Vale destacar que este tipo de cirurgia também é aconselhável para corrigir problemas estruturais do nariz."},"3":{"title":"Lipoenxertia Facial","descr":"A Lipoenxertia Facial é um procedimento que restaura o contorno e a forma jovem do rosto, bem como a rigidez da pele por meio da aplicação de gordura retirada do abdômen ou de outras partes do corpo, purificada e injetada nas áreas que necessitam da recuperação do seu volume natural."},"4":{"title":"Lifting Labial","descr":"Um dos procedimentos faciais que vem ganhando atenção nos últimos anos é o lifting labial, também chamado de lip lift ou lip lifting ele levanta o lábio superior, corrigindo a queda natural (que o preenchimento não consegue corrigir) e dá mais volume."},"5":{"title":"Lifting Frontal","descr":"Testa franzida, marcas de expressão, rugas e olhar cansado. Essas são apenas algumas das consequências do envelhecimento e entre as cirurgias plásticas, o lifting frontal é uma alternativa que auxilia na melhora da aparência."},"6":{"title":"Blefaroplastia","descr":"A região dos olhos, quando apresenta os efeitos de envelhecimento confere uma aparência cansada, causando desconforto e incômodo. A blefaroplastia é indicada para pacientes que apresentam alterações típicas do envelhecimento, como o excesso de pele nas pálpebras."},"7":{"title":"Preenchimento Cutâneo","descr":"A melhor indicação do ácido hialurônico se ocorre nos sulcos faciais que se formam com o passar dos anos como o sulco nasogeniano) e os sulcos ao redor dos lábios. Também pode ser utilizado para aumentar os lábios em pacientes com lábios finos."},"8":{"title":"Otoplastia","descr":"A otoplastia ou cirurgia plástica das orelhas atua na correção da orelha em abano. A orelha em abano consiste no afastamento das orelhas em relação a cabeça, deixando a orelha mais aparente e conferindo a impressão de que elas são maiores."},"9":{"title":"Braquioplastia","descr":"A braquioplastia é indicada para pacientes com flacidez na região dos braços. Isso pode ocorrer devido a maus hábitos alimentares, sedentarismo ou fatores genéticos. Muitas vezes esse problema estético nos braços pode incomodar e gerar insegurança."},"10":{"title":"Abdominoplastia","descr":"Assim como a lipoaspiração, a abdominoplastia é uma cirurgia feita para retirar o excesso de pele na barriga, remodelando a região. Muito indicada para pacientes que passaram por uma gravidez recente ou fizeram uma cirurgia bariátrica."},"11":{"title":"Lipoaspiração","descr":"Consiste na aspiração de gordura através de uma cânula com a finalidade de melhorar o contorno corporal e refazer a silhueta do corpo. Melhor indicada para áreas de gordura localizada, que não diminuem com exercício e dieta."},"12":{"title":"Reconstrução Mamária","descr":"A reconstrução da mama é conseguida através de várias técnicas de cirurgia plástica que tentam restaurar a mama considerando-se a forma, a aparência e o tamanho após a retirada do tumor (nodulectomia) ou da mama inteira (mastectomia)."},"13":{"title":"Ginecomastia","descr":"A correção da ginecomastia está indicada nos casos relacionados a influências hormonais na juventude e não regridem após a puberdade. Em casos relacionados ao aumento de peso também pode ser realizada se não houver reversão do quadro."},"14":{"title":"Mamoplastia","descr":"A mamoplastia de redução consiste na redução de mamas grandes ou aumento de mamas pequenas, elevação e simetrização destas. Além disso, pode ser utilizada com forma de reconstrução de mamas retiradas em casos de câncer."},"15":{"title":"Prótese de Mama","descr":"A cirurgia de implante de silicone é a cirurgia plástica mais realizada no Brasil. Elas aumentam o volume da mama. É indicada para mamas com volume pequeno, com leve queda, assimetrias e reconstruções após cirurgias oncológicas."},"16":{"title":"Cirurgia em Ex-obesos","descr":"Se você sofreu dramática redução ponderal, quer por dieta e exercício físico, quer seja por cirurgia bariátrica (cirurgia de obesidade), e atingiu seu peso ideal, então você pode ser um bom candidato a este tipo de cirurgia."},"17":{"title":"Cirurgias Combinadas","descr":"As associações em cirurgia plástica têm sido um recurso bastante utilizado. A grande vantagem destas associações de cirurgia é o bom resultado obtido em um único procedimento que traz grande economia de tempo e dinheiro para o paciente."},"18":{"title":"Ninfoplastia","descr":"A ninfoplastia ou cirurgia da intimidade consiste na correção da hipertrofia (aumento) dos pequenos lábios na região genital feminina, geralmente a remoção de gordura ou excesso de pele pode corrigir o aumento."}},"SurgerieItemPage1":{"i":"Voltar para a página de cirurgias","p":"Agende agora mesmo seu horário com o Dr. Thomas Benson.","deep-plane-facelift":{"title":"Deep Plane Facelift","descr":"A cirurgia de Lifting Facial Deep Plane é considerada uma das técnicas cirúrgicas mais avançadas e inovadoras para rejuvenescimento facial, combinando resultados mais naturais e duradouros com o benefício de não possuir praticamente nenhuma cicatriz visível.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Conheça mais detalhes</h2><p>O principal diferencial do Lifting Facial Deep Plane, como o próprio nome sugere, é a atuação em uma camada mais profunda dos músculos. Ela atua diretamente entre o sistema SMAS, ou Sistema Músculo-Aponeurótico Superficial, que provoca os sinais de envelhecimento facial e a camada muscular mais profunda, responsável pela expressão facial.</p><p>O principal objetivo do Lifting Facial Deep Plane está na liberação e reposicionamento das camadas musculares e de gordura, sem provocar tensão nos tecidos, resultando em uma aparência mais jovem e sem o aspecto de “pele esticada”.</p><p>Em geral, os ligamentos dos tecidos da face são liberados para um reposicionamento natural em todo o rosto e pescoço, restaura a forma e o volume das bochechas sem a necessidade da aplicação de preenchimento ou gordura. Também são liberados os ligamentos que prendem a mandíbula para que ela possa ser levantada, criando uma aparência de linha da mandíbula mais lisa e nítida.</p><p>Além da face, também é utilizada em conjunto com a cervicoplastia, permitindo um maior refinamento da área do pescoço e linha do maxilar com resultados mais duradouros.</p><br><div><div class=\\"ratio ratio-16x9\\"><iframe width=\\"1280\\" height=\\"720\\" src=\\"https://www.youtube.com/embed/741HqtRgGIM?si=sos8FUDdaEusQeR4\\" title=\\"Deep Plane: Porquê eu escolhi essa técnica inovadora\\" frameborder=\\"0\\" allow=\\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\\" allowfullscreen></iframe></div><p class=\\"pt-2 small\\"><strong>Porquê escolhi a técnica inovadora de rejuvenescimento facial Deep Plane Facelift</strong><br><em>Acompanhe a explicação do Dr. Thomas Benson</em></p></div><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Deep Plane vs. Liftings Tradicionais</h2><p>Uma das maiores preocupações dos pacientes está na busca por resultados mais naturais, sem a aparência esticada comum às técnicas tradicionais.</p><p>A razão para isso é que em outras técnicas mais comuns apenas as camadas mais superficiais da pele são reposicionadas e suturas são aplicadas para levantar o conjunto de músculos SMAS, deixando a pele com aspecto mais firme porém sem eliminar o problema de bochechas caídas.</p><p>Como resultado, muitos cirurgiões acabam realizando a correção por meio de lipoenxertia, muitas vezes fazendo com que as bochechas evidenciem a correção.</p><p>Além de resultados mais naturais, a recuperação de um Lifting Facial Deep Plane é mais rápida e simples. É comum em outros tipos de lifting facial o rompimento de vasos sanguíneos, o que ocasiona hematomas maiores e recuperação mais lenta.</p><br><div><div class=\\"ratio ratio-16x9\\"><iframe width=\\"1280\\" height=\\"720\\" src=\\"https://www.youtube.com/embed/gPs3-B48ffY?si=aHDo7uWaKcrINxR2\\" title=\\"Como funciona a técnica Deep Plane - Thomas Benson\\" frameborder=\\"0\\" allow=\\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\\" allowfullscreen></iframe></div><p class=\\"pt-2 small\\"><strong>Como funciona a técnica Deep Plane Facelift?</strong><br><em>Comentado pelo Dr. Thomas Benson</em></p></div><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Recuperação e cicatrizes</h2><p>A recuperação após um Lifting Facial Deep Plane geralmente envolve poucos hematomas e uma recuperação mais rápida por não existir cortes em vasos sanguíneos entre o músculo e a pele. Alguns hematomas e inchaço ao redor das áreas reposicionadas podem aparecer nos primeiros dias e desaparecerão gradualmente.</p><p>Alguns medicamentos para dor podem ser prescritos para ajudar o paciente a se sentir mais confortável durante o processo de cicatrização. Também é importante o uso de compressas frias para aliviar o inchaço, além do descanso para a recuperação.</p><p>O Lifting Facial Deep Plane possui incisões que cicatrizam com mínima ou nenhuma cicatriz visível. Como nesta técnica a pele não é separada dos músculos, não há tensão nas linhas de incisão depois que são fechadas, o que permite que a incisão cicatrize como uma linha imperceptível.</p><p>Principais benefícios do Lifting Facial Deep Plane</p><ul><li>Menor tempo cirúrgico</li><li>Resultados mais naturais</li><li>Restauração do volume natural</li><li>Remoção do excesso de pele</li><li>Pele mais lisa e com aspecto jovem</li><li>Recuperação mais rápida</li><li>Cicatrizes imperceptíveis</li><li>Resultados mais duradouros</li></ul><br><div><div class=\\"ratio ratio-16x9\\"><iframe width=\\"1280\\" height=\\"720\\" src=\\"https://www.youtube.com/embed/1rpzysLsi6w?si=RWWz_-x14TKRUYSv\\" title=\\"Deep Neck Lift explicado pelo Dr. Thomas Benson\\" frameborder=\\"0\\" allow=\\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\\" allowfullscreen></iframe></div><p class=\\"pt-2 small pb-0 mb-0\\"> <strong>Deep Necklift explicado pelo Dr. Thomas Benson</strong><br><em>Confira o vídeo</em></p></div></div>"},"rinoplastia":{"title":"Rinoplastia","descr":"Indicada para quem quer modelar o tamanho e a proporção do nariz, a rinoplastia é uma das cirurgias mais procuradas para finalidades estéticas. Vale destacar que este tipo de cirurgia também é aconselhável para corrigir problemas estruturais do nariz.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Conheça mais detalhes</h2><p>Dentre os diversos procedimentos de cirurgia plástica disponíveis atualmente, a rinoplastia (nome técnico para a cirurgia do nariz) é o tipo mais complexo de ser realizado com excelência.</p><p>O nariz é um dos elementos mais marcantes do rosto de uma pessoa e pequenas irregularidades no formato podem causar sérios problemas na autoestima do paciente. Atualmente, as técnicas de rinoplastia desenvolvidas conseguem corrigir essas imperfeições de forma a harmonizar a simétrica facial e auxiliar num melhor funcionamento do sistema respiratório.</p><p>Além da harmonia com o rosto, na prática, a rinoplastia pode melhorar a respiração, o sentido do olfato e trazer mais qualidade de vida para quem sofre tanto com deformidades adquiridas quanto congênitas.Em nossa clínica realizamos principalmente a técnica estruturada, que é uma técnica menos agressiva e com resultados mais naturais e esteticamente equilibrado para o rosto.</p><p>É a técnica utilizada por cirurgiões mais experientes em procedimentos faciais, separando todas as subunidades do nariz e normalmente retirando cartilagem do septo, fazendo as modificações das estruturas de forma precisa. Com isso, o resultado é muito mais duradouro e com menor risco de alterações futuras.</p><p>De forma geral, o médico avalia a proporção da face, os ângulos nasais, as características da pele e o que precisa ser melhorado também para a qualidade de vida. Por isso é muito importante que a escolha do médico seja criteriosa, afinal, a rinoplastia é um processo artesanal e que requer habilidades precisas e certeiras para que tudo funcione conforme o esperado.</p><p>Além disso, você encontra em nossa clínica o apoio de profissionais qualificados para sanar todas as suas dúvidas, seja referente ao processo cirúrgico ou aos cuidados pós-operatórios. Caso esteja considerando passar por uma rinoplastia, agende uma consulta e obtenha todas as informações necessárias para te auxiliar nessa decisão.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Vantagens da técnica estruturada</h2><p>É importante salientar que após uma cirurgia de Rinoplastia o nariz continua sofrendo o efeito de diversas forças, como por exemplo a da respiração que gera pressão negativa nas vias aéreas. Com isso, o tecido cicatricial que se formará em torno das cartilagens posicionadas poderá sofrer pequenas deformações com o tempo, até mesmo alterando a posição dessas cartilagens.</p><p>Por conta disso, a Rinoplastia Estruturada tem como objetivo o fortalecimento dessa estrutura nasal, o que contribui para resultados mais duradouros, além de maior precisão ao esculpir a cartilagem, proporcionando um resultado mais natural e harmonioso.</p><p>Além disso, dependendo do caso, o cirurgião poderá priorizar as incisões internas no nariz, o que contribui para que fiquem completamente imperceptíveis.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Anestesia</h2><p>Com os avanços em medicamentos e na tecnologia de equipamentos para controle e monitoramento do paciente, a anestesia geral se tornou a mais segura quando bem indicada.</p><p>Devemos levar em consideração fatores muito importantes como: doenças pré-existentes, exames pré-operatórios, profissionais competentes, equipamentos modernos e hospitais com infraestrutura adequada ao porte cirúrgico.</p><p>É de total relevância saber o histórico do paciente e ter uma avaliação clínica que permita indicar o procedimento.</p><p>O monitoramento adequado utilizando-se de todos os recursos tecnológicos hoje acessíveis, permitem o controle da frequência cardíaca, pressão arterial, oxigenação, controle das vias aéreas, manutenção da temperatura corpórea, prevenção de trombose e até mesmo determinação do nível de consciência dos pacientes.</p></div>"},"lipoenxertia-facial":{"title":"Lipoenxertia Facial","descr":"A Lipoenxertia Facial é um procedimento que restaura o contorno e a forma jovem do rosto, bem como a rigidez da pele por meio da aplicação de gordura retirada do abdômen ou de outras partes do corpo, purificada e injetada nas áreas que necessitam da recuperação do seu volume natural.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Conheça mais detalhes</h2><p>A Lipoenxertia Facial é uma das técnicas que mais revolucionou as cirurgias plásticas de Lifting Facial, além de ser uma das técnicas mais avançadas em cirurgia plástica nos últimos anos.</p><p>Diversos procedimentos de lifting facial foram criados com o objetivo de rejuvenescimento facial, a maioria deles concluindo em uma cirurgia mais extensa e com resultados menos naturais.Algo que foi notado durante esse período é que o rosto envelhece não somente devido à queda pela falta de suporte, mas também por perder o volume natural de bochechas, na linha do maxilar e sob os olhos.</p><p>É um procedimento que utiliza a gordura retirada do abdômen ou de outras partes do corpo, purificada e aplicada nas regiões do rosto que perderam volume, que além de oferecer resultados mais naturais também contribui na qualidade da pele e na redução de pequenas rugas e imperfeições.</p><p>Este procedimento restaura o contorno e a forma jovem do rosto, bem como a rigidez da pele. Diferentemente dos procedimentos de enxertia de gordura que utilizam técnicas anteriores, na Lipoenxertia Facial, a gordura passa por processamento e purificação, maximizando e melhorando a qualidade da pele e dos tecidos em geral.</p></div>"},"lifting-labial":{"title":"Lifting Labial","descr":"Um dos procedimentos faciais que vem ganhando atenção nos últimos anos é o lifting labial, também chamado de lip lift ou lip lifting ele levanta o lábio superior, corrigindo a queda natural (que o preenchimento não consegue corrigir) e dá mais volume.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Conheça mais detalhes</h2><p>A cirurgia de Lifting Labial é um procedimento que pode ser realizada tanto em pessoas de mais idade para rejuvenescimento facial, corrigindo a queda natural do lábio superior, quanto em jovens que tem como objetivo o aumento labial, já que ao elevar o lábio superior dá mais volume, expondo mais os dentes superiores e um sorriso mais harmônico.</p><p>Com o envelhecimento, uma das consequências é a perda de gordura nos lábios, fazendo com que eles cedam devido à perda de suporte.O lifting de lábios é o procedimento mais indicado para quem deseja corrigir altura e volume dos lábios de forma permanente, evitando a necessidade de aplicações constantes de preenchimento labial.</p><p>Quando você ouve o termo Lip Lifting, ou Lifting Labial, em geral, se refere a um lifting de lábio superior. A operação pode ser adaptada para elevar diferentes regiões do lábio, tornando-os mais modelados e com contorno mais definido.</p><p>Ao corrigir os casos de pacientes que têm uma grande distância entre o nariz e o lábio superior, é conferida uma aparência mais harmoniosa com o resto do rosto. Por esta razão, existem pacientes mais jovens que possuem lábio superior mais longo que se beneficiam imensamente com esta cirurgia. Quando realizado em pacientes mais velhos, ela restaura a aparência jovem do rosto. Essa alteração sutil faz com que as pessoas pareçam anos mais jovens e rejuvenescidas.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Resultados mais naturais</h2><p>O procedimento de Lifting Labial é frequentemente realizado em conjunto com as aplicações de laser. Para quem deseja principalmente o aumento de volume, em muitos casos é utilizada em conjunto a enxertia de gordura (ou lipoenxertia, um procedimento reconhecido mundialmente onde uma porção de gordura é retirada do abdômen ou de outras partes do corpo, purificada e injetada nas áreas necessárias), que além de oferecer resultados mais naturais também contribui na qualidade da pele e na redução de pequenas rugas e imperfeições.</p></div>"},"lifting-frontal":{"title":"Lifting Frontal","descr":"Testa franzida, marcas de expressão, rugas e olhar cansado. Essas são apenas algumas das consequências do envelhecimento e entre as cirurgias plásticas, o lifting frontal é uma alternativa que auxilia na melhora da aparência.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Conheça mais detalhes</h2><p>O Lifting Frontal é um procedimento cirúrgico para rejuvenescimento facial, suavizando as linhas de expressão e rugas na região da testa. O cirurgião eleva a pele e os tecidos da parte superior da face com o auxílio de uma câmera endoscópica com alta precisão, resultando em uma aparência mais jovem e renovada.</p><p>O Lifting Frontal é um procedimento cirúrgico para rejuvenescimento facial, suavizando as linhas de expressão e rugas na região da testa. O cirurgião eleva a pele e os tecidos da parte superior da face com o auxílio de uma câmera endoscópica com alta precisão, resultando em uma aparência mais jovem e renovada.</p><p>A técnica consiste em realizar pequenas incisões para que os ligamentos e músculos sejam reposicionados de forma que a face ganhe uma aparência mais jovem, amenizando o envelhecimento, reduzindo as marcas e podendo também arquear as sobrancelhas, com cicatrizes praticamente imperceptíveis.</p><p>Por conta das incisões menores, os pacientes que realizam um lifting frontal com via endoscópica passam por um período de recuperação menor, retornando às suas atividades normais mais cedo e com resultados mais duradouros comparados aos métodos mais comuns realizados.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Técnicas combinadas</h2><p>Antes de optar pelo lifting frontal, é imprescindível conversar com o cirurgião para o alinhamento das expectativas e dos resultados possíveis. O lifting frontal traz ótimos resultados quando realizado individualmente, porém é possível ir além e renovar a aparência como um todo utilizando-o em combinação com outros procedimentos.</p><p>Algumas das principais técnicas muito combinadas com o lifting frontal são: o lifting facial, que rejuvenesce a região da face e a blefaroplastia para a região dos olhos, dessa forma os resultados podem ser ainda mais potencializados.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Endotine® Forehead Device</h2><p>Uma das tecnologias que utilizamos em nossas cirurgias é o Endotine® Forehead Device, que é uma solução inovadora projetada especificamente para elevar o tecido da testa na cirurgia de Lifting Frontal. Sua estrutura única fornece vários pontos de contato com o tecido da testa, criando uma distribuição mais uniforme e suave da força de retenção.</p><p>Outras opções, como parafusos e suturas, normalmente fornecem apenas um ponto de contato que pode romper os tecidos moles, afetando adversamente a confiabilidade da elevação da sobrancelha.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Cuidados depois da cirurgia</h2><p>A recuperação após um Lifting Frontal via endoscopia possui um pós-operatório mais simples comparado às técnicas mais tradicionais. Em dez dias, a maioria dos pacientes já podem retomar suas atividades de forma normal.</p><p>Nos primeiros dias é comum o aparecimento de hematomas e inchaço na região das incisões, por isso a recomendação é para manter a cabeça elevada sempre que possível, realizando a aplicação de compressas frias para ajudar a reduzir o inchaço. Alguns pacientes sentem dores de cabeça entre 24 e 48 horas após a cirurgia. Os sinais mais visíveis da cirurgia devem desaparecer após três semanas e o crescimento normal dos cabelos será retomado nos meses seguintes.</p><p>Entre as indicações, vale lembrar que o paciente só pode lavar o cabelo depois de três dias e deve cuidar dos curativos conforme orientação médica, evitando o uso de maquiagem por alguns dias. Também é necessário evitar esforço físico, como baixar a cabeça por exemplo. Evitar a exposição ao sol também é importante para que a cicatriz fique protegida.</p><p>Em casos de dor ou desconforto, converse com o médico sobre analgésicos e anti-inflamatórios que podem ser usados.</p></div>"},"blefaroplastia":{"title":"Blefaroplastia","descr":"A região dos olhos, quando apresenta os efeitos de envelhecimento confere uma aparência cansada, causando desconforto e incômodo. A blefaroplastia é indicada para pacientes que apresentam alterações típicas do envelhecimento, como o excesso de pele nas pálpebras.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Conheça mais detalhes</h2><p>Pálpebras caídas, pés de galinha e olheiras de cansaço são sinais de envelhecimento comuns na região dos olhos. Para corrigir estes problemas, a blefaroplastia é uma cirurgia plástica que pode amenizar este quadro, rejuvenescendo o rosto e proporcionado a melhora da auto-estima e o bem-estar do paciente.</p><p>A blefaroplastia é o procedimento de elevação das pálpebras, no qual o cirurgião elimina as bolsas de gordura e ameniza o caimento natural do envelhecimento. As pálpebras superiores caídas são o resultado do excesso de flacidez da pele e as pálpebras inferiores ficam inchadas, bolsas se desenvolvem com a idade devido ao prolapso de gordura embaixo dos olhos. Essas mudanças geralmente contribuem para uma aparência mais envelhecida.</p><p>Para a pálpebra superior, são marcadas todas as linhas e vincos individuais das pálpebras para manter as incisões o mais invisíveis possível ao longo das dobras naturais. A incisão é feita e uma quantidade precisa de excesso de gordura, músculo e pele solta que estão contribuindo para o problema é removida.</p><p>Na inferior, a incisão é feita em um local imperceptível, apenas alguns milímetros abaixo da linha dos cílios e ao longo das dobras da pálpebra inferior. Mais uma vez, uma porção precisa de pele, gordura e músculos são removidos com precisão. Suturas extremamente finas são então utilizadas para fechar meticulosamente as incisões, minimizando assim a visibilidade de qualquer cicatriz.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Técnicas combinadas</h2><p>Para realizar a blefaroplastia, o paciente precisa estar em boas condições de saúde física e alinhar as expectativas emocionais com o cirurgião. Além de passar por avaliação médica, provavelmente o paciente terá que passar por exames laboratoriais de sangue.</p><p>Não é aconselhável o uso de remédios anticoagulantes antes da cirurgia. Bebida e cigarro também devem estar fora da rotina do paciente antes do procedimento e 8 horas antes da cirurgia, é necessário fazer jejum absoluto.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Cuidados depois da cirurgia</h2><p>Após a cirurgia é comum que a região operada fique sensível e um pouco inchada, por isso o tempo de repouso varia entre uma semana e um mês. Neste período, o cuidado deve ser redobrado para garantir uma cicatrização segura e uma recuperação adequada.</p><p>Por isso, preste atenção nas dicas:</p><ul><li>Evite exposição ao sol, vento e friagem;</li><li>Evite coçar os olhos;</li><li>Não deite de lado</li><li>Quando for fazer compressas, use soro fisiológico;</li><li>Durma com dois travesseiros para manter a cabeça elevada;</li></ul><p>Em caso de dúvida, marque o retorno ao médico;</p></div>"},"preenchimento-cutaneo":{"title":"Preenchimento Cutâneo","descr":"A melhor indicação do ácido hialurônico se ocorre nos sulcos faciais que se formam com o passar dos anos como o sulco nasogeniano) e os sulcos ao redor dos lábios. Também pode ser utilizado para aumentar os lábios em pacientes com lábios finos.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Conheça mais detalhes</h2><p>Com o tempo, é inevitável que marcas de expressão, sulcos faciais, rugas e sinais de envelhecimento fiquem visíveis em nossa pele. Por isso, manter a elasticidade, recuperar o colágeno e a consistência da pele é um desafio. Para solucionar estes problemas, o preenchimento cutâneo é um dos tratamentos possíveis.</p><p>Com uma técnica pouco invasiva, o procedimento consiste na aplicação do ácido hialurônico sobre o local desejado, geralmente com uma injeção e anestesia local. Além dessas vantagens, diferente de outros procedimentos, o paciente precisa sim ter alguns cuidados após o preenchimento mas não é necessário ficar em repouso.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Resultados</h2><p>Na prática, os resultados do preenchimento cutâneo duram de 15 a 18 meses. Com o ácido hialurônico, as rugas são literalmente preenchidas e as linhas de expressão ficam com um aspecto mais suave e discreto. Além desta finalidade, esta técnica também é muito indicada para pacientes que querem aumentar os lábios, contornar a maçã do rosto e corrigir o chamado “bigode chinês” (sulco nasogiano).</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Cuidados</h2><p>Todo procedimento estético precisa de uma avaliação médica e é sempre indicado que o paciente alinhe suas expectativas com a realidade. Com efeitos impressionantes, o preenchimento cutâneo é sim uma alternativa para as marcas do tempo, mas é importante lembrar que o envelhecimento é um processo natural.</p><p>Por isso, além do procedimento estético, nunca é demais reforçar alguns cuidados como:</p><ul><li>Cuidar da alimentação;</li><li>Se hidratar regularmente;</li><li>Evitar o excesso de exposição ao sol;</li></ul></div>"},"otoplastia":{"title":"Otoplastia","descr":"A otoplastia ou cirurgia plástica das orelhas atua na correção da orelha em abano. A orelha em abano consiste no afastamento das orelhas em relação a cabeça, deixando a orelha mais aparente e conferindo a impressão de que elas são maiores.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Conheça mais detalhes</h2><p>A chamada “orelha de abano” que provoca desproporção no tamanho e no formato das orelhas é um problema que atinge de 2% a 5% da população de acordo com a Sociedade Brasileira de Cirurgia Plástica.</p><p>Para corrigir este problema, a otoplastia é a cirurgia plástica mais indicada. Na prática, a otoplastia é realizada por meio de uma incisão atrás da orelha. Durante a cirurgia, o médico tira uma pequena parte da cartilagem e faz todo um processo para que as orelhas fiquem na posição mais adequada possível, aproximando as orelhas da cabeça.</p><p>Após o fechamento das incisões, coloca-se um curativo ao redor das orelhas por um período de 24 horas para proteger a região operada.</p><p>Os resultados da otoplastia em geral são muito positivos e a cirurgia não deixa cicatrizes profundas, considerando que os pontos ficam escondidos atrás das orelhas. Porém, vale lembrar que não é todo caso que terá 100% de simetria, afinal, a própria natureza é assimétrica.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Como e quando fazer</h2><p>Quanto mais cedo a cirurgia for feita, melhor será o resultado. É comum que pais fiquem com receio em qual a melhor hora para realizar a otoplastia em crianças que já nasceram com as orelhas proeminentes, e não é à toa, afinal a otoplastia é uma intervenção cirúrgica.</p><p>Contudo, a faixa etária dos 5 aos 7 anos é bastante indicada para a cirurgia, pois nesta fase a orelha da criança está totalmente formada e com o passar do tempo, a desproporção e o incômodo pode ser ainda maior.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Cuidados pós-operatórios</h2><p>Quando o cirurgião fecha as incisões, automaticamente a pessoa fica com um curativo ao redor da cirurgia em forma de capacete por um período de 24 horas. Depois deste tempo, o capacete é substituído por uma faixa de compreensão que precisa ficar no local durante um mês e para manter o sucesso da cirurgia a pessoa precisa naturalmente ter alguns cuidados.</p><p>São eles:</p><ul><li>Evitar exposição ao sol;</li><li>Não praticar esportes;</li><li>Evitar mexer e coçar a região;</li></ul><p>Ao seguir essas orientações, o paciente evita que os pontos se rompam, além de infecções e possibilidade de uma nova cirurgia.</p></div>"},"braquioplastia":{"title":"Braquioplastia","descr":"A braquioplastia é indicada para pacientes com flacidez na região dos braços. Isso pode ocorrer devido a maus hábitos alimentares, sedentarismo ou fatores genéticos. Muitas vezes esse problema estético nos braços pode incomodar e gerar insegurança.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Conheça mais detalhes</h2><p>Se você tem gorduras localizadas e flacidez nos braços que popularmente é conhecida como a \\"asa de morcego\\", a chamada braquioplastia ou lifting branquial pode ser a solução.</p><p>Com duas horas de duração, a cirurgia é feito sob anestesia local e sedação. Durante o procedimento, o cirurgião faz uma incisão na parte interna do braço e assim retira os excessos de pele e de gordura do local.</p><p>É comum que a braquioplastia também possa ser complementada com outros procedimentos, e, nestes casos, o paciente também passa por uma anestesia geral.</p><p>É importante lembrar que a cirurgia fica numa região muito exposta e, por isso, é comum que as cicatrizes apareçam até o período de recuperação completo que pode variar entre um e dois anos.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Qual a melhor técnica?</h2><p>Muita gente se pergunta se a braquioplastia é a melhor solução, e de fato, esta é uma dúvida muito pertinente. No momento da avaliação, o cirurgião pode avaliar junto com o paciente qual a melhor opção. Em alguns casos, o aumento da gordura pode ser resolvido com uma lipoaspiração.</p><p>Em outros, uma alimentação balanceada e hábitos saudáveis podem resolver o problema. Mas se nada funcionar, a braquioplastia é uma opção que traz resultados muito positivos. É importante entender o processo e tirar as dúvidas com um especialista de confiança.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Cuidados</h2><p>Após a cirurgia, os pacientes devem ficar de repouso num período de três a cinco dias. Além disso, é necessário manter os braços perto do corpo num período de até três semanas. É bom evitar esforço físico na região durante o primeiro mês para que a cicatrização dos tecidos ocorra sem o alargamento das cicatrizes.</p><p>O paciente também deve usar cintas de compressão durante um ou dois meses para que o inchaço da região operada seja reduzido. E por fim, se houver possibilidades, a drenagem linfática é uma boa ideia para otimizar a absorção do edema nesta fase de recuperação.</p></div>"},"abdominoplastia":{"title":"Abdominoplastia","descr":"Assim como a lipoaspiração, a abdominoplastia é uma cirurgia feita para retirar o excesso de pele na barriga, remodelando a região. Muito indicada para pacientes que passaram por uma gravidez recente ou fizeram uma cirurgia bariátrica.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Conheça mais detalhes</h2><p>Assim como a lipoaspiração, a abdominoplastia é uma cirurgia que pode ser utilizada para remodelar a região do abdômen. Muito indicada para pacientes que passaram por uma gravidez recente ou fizeram uma cirurgia bariátrica, a abdominoplastia consiste no tratamento do excesso de pele, da gordura localizada e da correção do afastamento dos músculos que ficam no abdome.</p><p>A cirurgia dura em média 3 horas e durante este período o médico precisa fazer uma incisão inferior do abdome. Depois dessa incisão, a pele e a gordura são separadas da parede muscular e, desta forma, é possível aproximar os músculos que reforçam a parede abdominal. Feito isso, o cirurgião retira o excesso de pele e de gordura e fecha a incisão.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Antes e depois da cirurgia</h2><p>Antes da cirurgia, o paciente deve evitar o consumo de medicamentos, o uso de cigarros e bebidas e seguir a regra do jejum total oito horas antes da cirurgia. Depois da alta (geralmente o paciente pode ir para casa no dia seguinte à cirurgia), o repouso pode variar de 10 dias a dois meses, mas independentemente deste tempo, é necessário seguir alguns cuidados para que a abdominoplastia tenha os melhores resultados possíveis.</p><p>São eles:</p><ul><li>Dormir de barriga para cima e com as pernas sempre flexionadas (pelo menos nos primeiros 15 dias);</li><li>Tomar banho de chuveiro é possível já no dia seguinte. E a equipe cirúrgica realiza a troca de curativos após 4 dias;</li><li>Usar cinta modeladora e meias de compressão (a cinta modeladora deve ser retirada apenas para tomar banho, porque é ela que alivia as dores e evita que as cicatrizes sejam complicadas). No caso, das meias de compreensão, a retirada só pode ser feita quando a pessoa retorna as atividades diárias;</li><li>Troca de curativo (a primeira troca deve ser feita 4 dias depois da cirurgia, pela equipe médica, de forma delicada, seguindo as orientações médicas);</li><li>Exercícios físicos leves (não é recomendado que o paciente pegue peso após a cirurgia, mas neste caso, é bom movimentar as penas a cada duras horas para evitar coágulos na região operada);</li></ul></div>"},"lipoaspiracao":{"title":"Lipoaspiração","descr":"Consiste na aspiração de gordura através de uma cânula com a finalidade de melhorar o contorno corporal e refazer a silhueta do corpo. Melhor indicada para áreas de gordura localizada, que não diminuem com exercício e dieta.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Conheça mais detalhes</h2><p>A famosa “lipo”, também chamada de lipoaspiração é uma cirurgia muito procurada e conhecida pelas mulheres que querem remodelar a barriga e o corpo, reduzindo as gorduras localizadas.</p><p>Além do abdome, a lipoaspiração também pode ser feita em outras regiões do corpo como cintura, dorso alto e baixo, culote, face interna dos joelhos e até mesmo nos braços.</p><p>A equipe utiliza soro fisiológico e medicação sobre a gordura que será aspirada e no fim todas as incisões são fechadas e protegidas com um curativo, seguidas de uma cinta compressiva que serve para diminuir o inchaço. A lipoaspiração dura em média de 1 a 3 horas, dependendo do caso.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Variedades da lipoaspiração</h2><p>A lipoescultura consiste numa variação da lipoaspiração onde, além dos procedimentos usuais da lipoaspiração, se realiza a colocação da gordura (procedimento conhecido como lipoenxertia) retirada da própria paciente em outras regiões.</p><p>A região mais frequente onde se injeta gordura é a glútea (nádegas), mas outras regiões podem ser endereçadas como depressões localizadas (congênitas ou resultantes de cirurgias prévias), sulcos da face (sulco nasogeniano) e lábios.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Cuidados depois da cirurgia</h2><p>Para que os resultados sejam mais efetivos, o paciente precisa investir na recuperação e nos cuidados pós-operatórios. A cinta compressiva por exemplo, deve ser usada durante a maior parte do tempo no primeiro mês e só pode ser retirada na hora do banho. No segundo mês, ainda é preciso usá-la durante 12 horas. Além disso é importante beber muita água, deixando o corpo hidratado e adotar uma dieta saudável e balanceada.</p><p>Se houver possibilidades, fazer drenagem linfática também é uma coisa que potencializa os resultados. É importante que o paciente não fume pelo menos um mês depois da cirurgia e não faça exercícios físicos pesados. A exposição ao sol também deve ser evitada. Cada caso tem suas particularidades, mas ao seguir esses cuidados, o paciente tem mais chances de uma recuperação e cicatrização tranquila.</p></div>"},"reconstrucao-mamaria":{"title":"Reconstrução Mamária","descr":"A reconstrução da mama é conseguida através de várias técnicas de cirurgia plástica que tentam restaurar a mama considerando-se a forma, a aparência e o tamanho após a retirada do tumor (nodulectomia) ou da mama inteira (mastectomia).","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Conheça mais detalhes</h2><p>Indicada para mulheres que tiveram os seios removidos por causa de um problema de saúde, ou para quem quer alterar a forma, o tamanho e a aparência dos seios, a reconstrução mamária é uma opção bastante procurada.</p><p>O tempo da cirurgia varia muito conforme a situação da paciente e é comum que além da reconstrução mamária, o cirurgião opte por procedimentos complementares.</p><p>De forma geral, a reconstrução mamária se divide em fases, desde a avaliação, a retirada de excessos a reconstrução das glândulas e não existe uma regra para o que vem primeiro, já que cada caso tem suas particularidades.</p><p>Durante a cirurgia, é possível reconstruir desde o mamilo até a aréola inteira. Para este tipo de procedimento, também vale destacar a necessidade de uma anestesia geral.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Preparação da cirurgia</h2><p>Independente do contexto, toda pessoa que passa por uma reconstrução mamária precisa seguir alguns passos. O primeiro é uma conversa com o especialista para alinhar expectativas.</p><p>Depois disso, é preciso fazer exames laboratoriais como hemograma, eletrocardiograma ultrassom e mamografia.</p><p>O uso de medicamentos também deve ser cortado, especialmente se forem aspirinas ou anti-inflamatórios e remédios naturais.</p><p>Caso o paciente fume, é importante largar o cigarro antes da cirurgia e por fim, é necessário ficar em jejum absoluto oito horas antes do procedimento.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Após o procedimento</h2><p>Além de evitar esforços físicos e exposição ao sol, o paciente precisa ficar atento a um dreno temporário que é colocado sobre a pele para sangue e fluído.</p><p>Seguir os cuidados de higiene e de curativo e tomar os medicamentos ajuda a reduzir o risco de infecção.</p><p>Além disso, não é aconselhável fumar após a cirurgia e é recomendado ter uma alimentação adequada para que a recuperação seja de sucesso. Assim como nas demais cirurgias, é necessário que o paciente faça acompanhamento médico, informando o especialista de todas as condições da cirurgia.</p></div>"},"ginecomastia":{"title":"Ginecomastia","descr":"A correção da ginecomastia está indicada nos casos relacionados a influências hormonais na juventude e não regridem após a puberdade. Em casos relacionados ao aumento de peso também pode ser realizada se não houver reversão do quadro.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Conheça mais detalhes</h2><p>A ginecomastia é uma condição na qual homens possuem um aumento de tecido nas glândulas mamárias que atinge 60% dos homens.</p><p>Geralmente a cirurgia é indicada para os homens que mesmo após a fase da puberdade, continuam sofrendo com este problema e o tempo de cirurgia varia muito conforme a situação das glândulas, durando geralmente entre uma e duas horas.</p><p>Em casos onde existe apenas o acúmulo da gordura e a glândula não aumenta tanto assim, uma lipoaspiração já resolve o problema.</p><p>Agora quando a glândula mamária está com uma condição de hipertrofia, o cirurgião precisa realizar uma incisão simples para retirar este excesso.</p><p>Dependendo do caso, pode haver necessidade de técnicas combinadas, principalmente quando há excesso de pele e flacidez.</p><p>Nesta situação, além de remover os tecidos, o especialista precisa adequar a posição do mamilo e da aréola para que o tórax fique em harmonia com os mamilos.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Antes e depois</h2><p>Além da avaliação médica, o paciente que passa pela ginecomastia precisa realizar exames pré-operatórios de rotina e avaliação das mamas com uma ultrassonografia.</p><p>Ao seguir essas recomendações, a recuperação do paciente acontece de forma gradual e saudável e em caso de qualquer sintoma como falta de ar, dores no peito ou batimentos cardíacos anormais, o cirurgião deve ser procurado.</p><p>Depois de operar, o paciente precisa seguir alguns cuidados como, por exemplo:</p><ul><li>Dormir de barriga para cima durante 30 dias;</li><li>Fazer acompanhamento médico;</li><li>Não fumar durante 15 dias após a cirurgia;</li><li>Usar um colete de elástico para melhorar a aderência da pele ao tórax durante 30 dias;</li></ul></div>"},"mamoplastia":{"title":"Mamoplastia","descr":"A mamoplastia de redução consiste na redução de mamas grandes ou aumento de mamas pequenas, elevação e simetrização destas. Além disso, pode ser utilizada com forma de reconstrução de mamas retiradas em casos de câncer.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Conheça mais detalhes</h2><p>Assim como a prótese de silicone, a mamoplastia é uma cirurgia para os seios, com a diferença que ela pode aumentar ou reduzir o tamanho dessa parte do corpo.</p><p>No caso da mamoplastia de aumento, o cirurgião também realiza incisões na região para implantar a prótese com o formato, a textura e o tamanho adequado escolhido pela mulher.</p><p>Já na mamoplastia redutora, o cirurgião faz algumas incisões que começam ao redor da aréola e vão até o sulco mamário e horizontal desta parte do corpo que também é conhecida como \\"T\\" invertido.</p><p>Depois disso, é feita a mobilização do tecido mamário e a redução do excesso de mama conforme a necessidade da paciente.</p><p>Além de diminuir ou aumentar os seios, a mamoplastia também é indicada para a reconstrução das mamas que sofreram acidentes ou retiradas em função de um câncer.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Antes e depois</h2><p>Assim como nos outros procedimentos, nunca é demais lembrar que a paciente deve estar segura de si para aderir a mamoplastia. É necessário também realizar exames de rotina como os de sangue e eletrocardiograma além de exames de imagem como a mamografia, ultrassonografia e seguir toda as orientações médicas em relação a jejum e ao tempo de internação.</p><p>Depois da mamoplastia, a mulher deve redobrar os cuidados na fase pós-operatória, tais como:</p><ul><li>Usar sutiã cirúrgico ou sutiã de sustentação durante 30 dias;</li><li>Não dormir de lado por um mês e evitar dormir na posição de bruços;</li><li>Evitar exercícios físicos por 90 dias;</li><li>Não passar creme no corte cirúrgico;</li><li>Cuidar da higiene e dos pontos com delicadeza;</li></ul></div>"},"protese-de-mama":{"title":"Prótese de Mama","descr":"A cirurgia de implante de silicone é a cirurgia plástica mais realizada no Brasil. Elas aumentam o volume da mama. É indicada para mamas com volume pequeno, com leve queda, assimetrias e reconstruções após cirurgias oncológicas.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Conheça mais detalhes</h2><p>Queridinha entre as mulheres que desejam aumentar o volume e a forma dos seios, a prótese de mama é uma cirurgia muito procurada em todos os consultórios de cirurgia plástica.</p><p>Com anestesia peridural ou geral, a cirurgia de prótese de mama dura em média duas horas. Durante o procedimento, o cirurgião faz uma incisão no sulco mamário ou na região da axila. Geralmente, a do sulco mamário é a opção mais utilizada, considerando o acesso a região onde a prótese será colocada e escondida pelo sutiã.</p><p>Vale lembrar que a posição do implante depende muito da anatomia do paciente, mas em um contexto geral há duas formas: abaixo da glândula mamária (procedimento conhecido como subglandular/subfascial) ou abaixo do músculo peitoral (submuscular).</p><p>Além dos exames pré-operatórios da rotina, é comum que o cirurgião peça para a paciente exames de imagem que são complementares como ultrassom de mama ou mamografia.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Antes e depois</h2><p>Conversar com o médico e avaliar qual o melhor formato, material e tamanho da prótese de silicone é uma coisa muito importante para fazer antes da cirurgia.</p><p>É bom evitar medicamentos e estar em boas condições de saúde física e emocional para fazer a cirurgia e mesmo depois da prótese implantada os cuidados continuam.</p><p>No primeiro mês, por exemplo, é fundamental evitar esforços físicos nos braços. Ou seja: nada de academia ou outros exercícios físicos pesados.</p><p>Também é importante usar sutiã por 24h no primeiro mês e não é recomendado dormir de bruços, em cima da região operada. Se você for fumante, esqueça o cigarro após o primeiro mês da cirurgia. Contrariar essa indicação afeta a cicatrização da cirurgia e consequentemente os resultados.</p><p>Também não se deve tomar sol em um período de 2 a 3 meses após o procedimento. Mesmo depois deste tempo, a exposição pode ser realizada desde que as cicatrizes estejam cobertas com um esparadrapo branco.</p></div>"},"cirurgia-em-ex-obesos":{"title":"Cirurgia em Ex-obesos","descr":"Se você sofreu dramática redução ponderal, quer por dieta e exercício físico, quer seja por cirurgia bariátrica (cirurgia de obesidade), e atingiu seu peso ideal, então você pode ser um bom candidato a este tipo de cirurgia.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Conheça mais detalhes</h2><p>Em situações de ganho ou de perca de peso em um curto período, é comum que a elasticidade da pele se perca, dando lugar a gordura e a flacidez. Para corrigir este problema, a cirurgia de contorno temporal é uma das mais indicadas por especialistas.</p><p>Durante o procedimento, o cirurgião retira o excesso de pele, e desta forma remodela o corpo e \\"levanta\\" a pele caída e enrugada.</p><p>Geralmente a cirurgia para ex-obesos está associada a outros tipos de cirurgia como a lipoaspiração e o lifting branquial, por exemplo. Essa necessidade é avaliada conforme o quadro do paciente e independente do número de combinações, uma avaliação médica antes da cirurgia é muito importante para que os resultados sejam alcançados.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Antes e depois da cirurgia</h2><p>De forma geral, a idade do paciente e o número de áreas com flacidez bem como a qualidade da pele afetam diretamente o sucesso da cirurgia. Assim como nos demais procedimentos, o paciente precisa realizar alguns exames de rotina e se preparar para o período pré-operatório não tomando medicamentos e nem ingerindo álcool e cigarro.</p><p>Após a cirurgia, é importante que a pessoa não pegue sol em um período de dois meses e, além disso a higiene deve ser feita com anti-séptico de forma cuidadosa sobre as incisões.</p><p>Cuidar da alimentação e manter o corpo hidratado também é muito importante para a preservação dos resultados. Por isso, fazer acompanhamento médico e nutricional é uma boa dica para quem passa pela cirurgia de contorno corporal.</p><p>O tempo total de recuperação varia conforme o número de combinações cirúrgicas para cada caso.</p></div>"},"cirurgias-combinadas":{"title":"Cirurgias Combinadas","descr":"As associações em cirurgia plástica têm sido um recurso bastante utilizado. A grande vantagem destas associações de cirurgia é o bom resultado obtido em um único procedimento que traz grande economia de tempo e dinheiro para o paciente.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Conheça mais detalhes</h2><p>No universo das cirurgias plásticas, as cirurgias combinadas têm crescido bastante e chamam a atenção de pacientes que desejam corrigir mais de uma imperfeição ao mesmo tempo.</p><p>Um destes exemplos é a própria cirurgia para ex-obesos que dependendo da flacidez e da situação pode ser combinada com uma lipoaspiração por exemplo, mas as combinações não param por aí.</p><p>Muitas pessoas que fazem lipoaspiração também optam pela abdominoplastia e como ambas cirurgias são realizadas na barriga, com o objetivo de secar a gordura localizada, a combinação potencializa os resultados.</p><p>Outras pessoas fazem questão de combinar a lipoaspiração com uma mamoplastia por exemplo e ainda há os que fazem uma rinoplastia com uma blefaroplastia e assim por diante.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Como saber se você é um(a) bom(boa) candidato(a)?</h2><p>A combinação de cirurgias é um recurso que sem dúvidas, poupa o tempo e a disposição dos pacientes. Mas é bom lembrar que tudo deve passar pela avaliação médica, considerando aspectos como tempo de recuperação e condições físicas de saúde do paciente.</p><p>É importante lembrar que somente a vontade sem a real necessidade não é um motivo suficiente para realizar mais de uma cirurgia. Em casos que o paciente sofre com doenças como pressão alta, anemia e diabetes, por exemplo, as cirurgias combinadas não são uma boa opção.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Antes e depois da cirurgia</h2><p>Além da avaliação médica, os cuidados com exames de rotina, jejum e ausência de cigarro também prevalecem para as cirurgias combinadas. No caso dos cuidados pós-operatórios, a necessidade varia conforme o tipo de cirurgia.</p><p>Em geral, a exposição ao sol, a higiene e o repouso são coisas que ajudam e interferem na recuperação do paciente.</p></div>"},"ninfoplastia":{"title":"Ninfoplastia","descr":"A ninfoplastia ou cirurgia da intimidade consiste na correção da hipertrofia (aumento) dos pequenos lábios na região genital feminina, geralmente a remoção de gordura ou excesso de pele pode corrigir o aumento.","content":"<div class=\\"container\\"><h2 class=\\" mb-40 mb-xs-30\\">Conheça mais detalhes</h2><p>A Ninfoplastia é um procedimento cirúrgico que visa auxiliar mulheres com hipertrofia na região íntima.</p><p>E, apesar de ser um procedimento cirúrgico que pode melhorar diretamente o bem-estar e autoestima da paciente, muitas mulheres ainda o desconhecem ou têm dúvidas sobre o assunto.</p><p>Se você é uma das que possui dúvidas sobre a Ninfoplastia, continue lendo esse post e descubra:</p><br><strong>• O que é a Ninfoplastia;</strong><br><br><strong>• Para quem ela é indicada;</strong><br><br><strong>• Quais são os benefícios gerados por esse procedimento;</strong><br><br><strong>• Como funciona a Ninfoplastia;</strong><br><br><strong>• Quem pode fazer esse tipo de procedimento.</strong><br><br><strong>Confira!</strong><br><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Ninfoplastia: O que é?</h2><p>A Ninfoplastia se trata de um procedimento cirúrgico que faz a correção de imperfeições relacionadas ao tamanho dos pequenos lábios.</p><p>Essa estrutura fica situada na entrada da vagina e é responsável por proteger essa região. Quando os pequenos lábios são hipertrofiados, além de gerar desconforto estético em muitas mulheres, também pode prejudicar as relações sexuais, causando dor e desconforto.</p><p>Por esse e outros motivos é que muitas mulheres acabam aderindo a Ninfoplastia para a correção desse tipo de problema.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Para quem é indicada a Ninfoplastia?</h2><p>Na maioria dos casos, este procedimento é indicado para mulheres que se sentem desconfortáveis esteticamente com a estrutura dos seus pequenos lábios ou que sentem dor durante a relação sexual ocasionada por esse tipo de alteração. Mas, também existem os casos clínicos onde essa cirurgia se faz necessária.</p><p>Em alguns quadros, a hipertrofia é tão grave que a paciente sente muita dificuldade na hora de fazer a higienização correta da vagina. Isso gera o acúmulo de secreções, o que pode gerar uma série de complicações, desde candidíase, até infecções urinárias.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Quais são os benefícios da Ninfoplastia?</h2><p>A Ninfoplastia traz uma série de benefícios para a mulher. Começando pelo fato da autoestima melhorar bastante, tendo em vista que a hipertrofia dos pequenos lábios pode afetar diretamente o emocional da paciente.</p><p>Além disso, a dor nas relações sexuais geradas em função da hipertrofia desaparece com o tempo, logo após o procedimento, fazendo com que a mulher consiga ter uma vida sexual saudável, sem qualquer incômodo.</p><p>Isso sem contar na parte da higiene, que se torna mais fácil para a paciente que antes tinha dificuldades por conta do excesso de pele na região dos pequenos lábios.</p><p>Basicamente, a Ninfoplastia afeta diretamente o bem-estar da mulher, melhorando a sua qualidade de vida.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Como funciona</h2><p>A Ninfoplastia é feita utilizando anestésico e a paciente pode ou não ser sedada. Ela dura entre quarenta minutos e uma hora.</p><p>Durante a operação, o cirurgião irá cortar uma parte dos pequenos lábios, a fim de deixá-los menores. Em seguida, ele fará a reconstrução deles, para que a paciente não fique com qualquer tipo de cicatriz.</p><p>Na verdade, após a recuperação dificilmente é possível perceber que a mulher passou por uma Ninfoplastia.</p><p>Um dos grandes diferenciais dessa intervenção cirúrgica é que a sutura é feita com fios absorvíveis. Ou seja, eles serão absorvidos de forma natural pelo organismo, sendo desnecessária a volta da paciente ao hospital para retirada dos pontos.</p><p>De modo geral a paciente tem alta no mesmo dia do procedimento. É possível retornar às atividades diárias em três dias, e a ter relações sexuais em três semanas.</p><br><h2 class=\\"pt-10 mb-40 mb-xs-30\\">Quem pode fazer a Ninfoplastia?</h2><p>Apesar de ser uma intervenção cirúrgica relativamente simples, precisa ser realizada por alguém especializado na área. Do contrário, a paciente corre o risco de não ter o resultado desejado, e ainda ficar com cicatrizes na sua região íntima.</p></div>"}},"BeforeAfter":{"metadata":{"title":"Antes e Depois || Dr. Thomas Benson","description":"Veja os resultados transformadores dos procedimentos realizados pelo Dr. Thomas Benson. Rejuvenescimento facial com precisão, cicatrizes imperceptíveis e depoimentos de pacientes satisfeitos com resultados naturais e harmoniosos."},"h2":"Antes e Depois","atext":"Resultados que refletem excelência e precisão.","p":"Agende agora mesmo seu horário com o Dr. Thomas Benson."},"BeforeAfterMassonry":{"filters":{"all":"Casos","scars":"Cicatrizes","post-surgical":"Pós-cirúrgicos"},"itemdescr":"Clique para ver o resultado"},"Result":{"metadata":{"title":"Resultado || Dr. Thomas Benson","description":"Resultado de excelência do procedimento realizado pelo Dr. Thomas Benson com antes e depois."},"i":"Voltar para a página inicial","atext":"Resultado","p":"As novas técnicas de rejuvenescimento facial como o Deep Plane e o Deep Neck trazem várias vantagens aos resultados.","h2":"Detalhes","proceduresb":"Procedimentos:","descriptionb":"Descrição:","p_2":"Não há resultados disponíveis por aqui.","ibefore":"Anterior","iall":"Todos os resultados","iafter":"Próximo"},"portfolios1":{"result1":{"procedures":"Blefaroplastia completa (Sup. / Inf.), Deep Plane | MADE, Enxertia, Laser CO2.","descriptionInt":"<div class=\\"container\\"><br/><p>Neste caso, a paciente buscava um rejuvenescimento facial profundo, com foco na região dos olhos e no contorno facial, e o Dr. Thomas Benson propôs uma combinação personalizada de procedimentos para alcançar um resultado natural e harmônico.</p><p>A Blefaroplastia Completa, que envolveu tanto a pálpebra superior quanto a inferior, foi fundamental para corrigir a flacidez e os excessos de pele, proporcionando um olhar mais aberto, descansado e jovial. A Blefaroplastia Superior suavizou as linhas pesadas na área das pálpebras, enquanto a Inferior ajudou a reduzir as bolsas de gordura e suavizar as rugas finas, contribuindo para um olhar mais revigorado.</p><p>A combinação com o Deep Plane Facelift e a técnica MADE (Minimal Access Deep Plane) foi decisiva para um rejuvenescimento mais profundo, garantindo um lifting eficaz das estruturas faciais sem comprometer a naturalidade. A enxertia de gordura foi utilizada para reposicionar volume nas áreas onde havia perda de gordura, proporcionando um contorno mais jovem e equilibrado, restaurando as proporções faciais.</p><p>O uso do Laser CO2 complementou o tratamento, melhorando a textura da pele, suavizando cicatrizes e linhas finas, além de promover um aspecto mais uniforme e luminoso. Cada um desses procedimentos atuou de forma sinérgica, atendendo às necessidades específicas da paciente e proporcionando um resultado global de rejuvenescimento, com um olhar mais aberto e descansado e um rosto mais jovem, firme e harmonioso.</p><p>A combinação de Blefaroplastia, Deep Plane Facelift, MADE, enxertia de gordura e Laser CO2 demonstrou a habilidade do Dr. Thomas Benson em personalizar tratamentos para cada paciente, oferecendo resultados excepcionais e naturais.</p></div>"},"result2":{"procedures":"Deep Plane | Deep Neck, Enxertia, Laser CO2.","descriptionInt":"<div class=\\"container\\"><br/><p>A paciente optou por um rejuvenescimento completo com foco na face e pescoço, e o Dr. Thomas Benson combinou técnicas avançadas para garantir um resultado natural e harmônico.</p><p>O Deep Plane Facelift e o Deep Neck Lift proporcionaram um lifting profundo, restaurando a firmeza da pele e suavizando a flacidez tanto na face quanto no pescoço. A enxertia de gordura foi utilizada para devolver volume às áreas com perda de gordura, criando um contorno mais equilibrado e jovem.</p><p>O Laser CO2 complementou o tratamento, melhorando a textura da pele, suavizando rugas e manchas, e conferindo uma aparência radiante.</p><p>O resultado final foi uma transformação que trouxe um rejuvenescimento natural, com a face e pescoço visivelmente mais firmes e revitalizados.</p></div>"},"result3":{"procedures":"Blefaroplastia completa (Sup. / Inf.), Deep Plane | Deep Neck, Enxertia, Liplift.","descriptionInt":"<div class=\\"container\\"><br/><p>A paciente procurou o Dr. Thomas Benson em busca de um rejuvenescimento completo e natural, focado na área dos olhos e no contorno facial. A Blefaroplastia Completa (superior e inferior) corrigiu a flacidez das pálpebras e reduziu as bolsas de gordura, proporcionando um olhar mais descansado e jovem. O Deep Plane Facelift combinado com o Deep Neck Lift promoveu um rejuvenescimento profundo na face e pescoço, restaurando a firmeza e definição da pele.</p><p>A enxertia de gordura devolveu volume nas áreas que perderam preenchimento, e o Liplift realçou os lábios, tornando-os mais definidos e harmoniosos. O resultado foi uma aparência rejuvenescida e equilibrada, com um contorno facial mais suave e natural.</p></div>"},"result4":{"procedures":"Deep Plane | Deep Neck, Enxertia, Laser CO2, Liplift, Susp. sobrancelha.","descriptionInt":"<div class=\\"container\\"><br/><p>A combinação de procedimentos proporcionou um resultado de rejuvenescimento completo e harmônico, com cada técnica complementando a outra de forma precisa e eficaz. O Deep Plane Facelift, aliado ao Deep Neck Lift, trabalhou tanto na face quanto no pescoço, restaurando a firmeza e definição das áreas mais afetadas pela flacidez. A enxertia de gordura foi fundamental para devolver volume nas regiões que naturalmente perdem essa substância com o envelhecimento, trazendo equilíbrio e suavidade ao contorno facial.</p><p>O Laser CO2 atuou de forma complementar, melhorando a textura da pele, suavizando rugas finas e manchas, enquanto o Liplift proporcionou lábios mais naturais e proporcionais, valorizando o sorriso sem exageros. A suspensão de sobrancelhas elevou a área dos olhos, conferindo um olhar mais descansado e revigorado.</p><p>Cada um desses procedimentos foi cuidadosamente escolhido para atuar em diferentes camadas e aspectos do envelhecimento facial, garantindo um resultado harmonioso e de aparência natural, sem sobrecarregar nenhuma área específica. O trabalho sinérgico entre as técnicas garantiu uma transformação profunda e equilibrada, com um rejuvenescimento completo que respeitou as características únicas da paciente.</p></div>"},"result5":{"procedures":"Deep Plane | Deep Neck, Enxertia, Laser CO2.","descriptionInt":"<div class=\\"container\\"><br/><p>A paciente optou por um rejuvenescimento completo com foco na face e pescoço, e o Dr. Thomas Benson combinou técnicas avançadas para garantir um resultado natural e harmônico. O Deep Plane Facelift e o Deep Neck Lift proporcionaram um lifting profundo, restaurando a firmeza da pele e suavizando a flacidez tanto na face quanto no pescoço.</p><p>A enxertia de gordura foi utilizada para devolver volume nas áreas que apresentavam perda de gordura, criando um contorno mais equilibrado e jovem. O Laser CO2 complementou o tratamento, melhorando a textura da pele, suavizando rugas e manchas, e conferindo uma aparência radiante. O resultado final foi uma transformação que trouxe um rejuvenescimento natural, com a face e pescoço visivelmente mais firmes e revitalizados.</p></div>"},"result6":{"procedures":"Deep Plane | Deep Neck, Enxertia, Laser CO2, Susp. sobrancelha.","descriptionInt":"<div class=\\"container\\"><br/><p>Neste caso, a paciente buscou uma transformação completa, com foco no rejuvenescimento da face e pescoço, e o Dr. Thomas Benson elaborou um plano de tratamento integrado, combinando técnicas de vanguarda para um resultado natural e sofisticado.</p><p>O Deep Plane Facelift foi o ponto de partida, proporcionando um rejuvenescimento profundo e duradouro na face, tratando a flacidez e promovendo uma aparência mais firme e descansada. Em conjunto, o Deep Neck Lift restaurou a definição e firmeza da região do pescoço, uma área que frequentemente revela sinais de envelhecimento. Juntas, essas técnicas ofereceram um rejuvenescimento completo, com a face e o pescoço se tornando mais harmônicos e proporcionais.</p><p>A enxertia de gordura foi usada para restaurar o volume perdido ao longo dos anos, especialmente nas áreas onde a gordura subcutânea é mais susceptível à perda, como as bochechas e a região temporal. Isso garantiu um contorno mais suave e jovem, além de proporcionar uma aparência mais equilibrada e natural.</p><p>O Laser CO2 complementou esse rejuvenescimento, melhorando a textura da pele e tratando manchas, rugas finas e pequenas imperfeições, proporcionando uma pele mais suave e radiante. Por fim, a suspensão de sobrancelhas foi realizada para elevar a região das sobrancelhas, proporcionando um olhar mais aberto e rejuvenescido, sem perder a expressividade natural da paciente.</p></div>"}},"RelatedProject10":{"h2":"Outros Resultados","itemdescr":"Clique para ver o resultado"},"compTeam":{"role":"Resultado final","p":"Cicatrizes.","span":"Cicatrizes sutis com técnicas de precisão e refinamento."},"compAbout":{"p":"<p>Doutor em Medicina (PhD) pelas prestigiadas Universidade de São Paulo (USP), no Brasil, e Doutor em Medicina (PhD) pela Universidade de Hamburgo (UKE – Universitätsklinik Eppendorf Hamburg) na Alemanha, o Dr. Thomas construiu sua carreira nas duas instituições mais respeitadas na área médica.<br/><br/>Ele também é o único cirurgião plástico no Brasil com título de especialista pelo European Board of Plastic Surgery (EBOPRAS),após ter feito sua prova de especialista em Bruxelas, Bélgica e em Bern, Suíça para obter seu certificado. Dr. Thomas Benson possui títulos de especialista no Brasil sendo membro titular da SBCP e também pelo governo Alemão.<br/><br/>Sua formação inclui residência em Cirurgia Geral e Cirurgia Plástica no Hospital das Clínicas da USP, pós graduação em microcirurgia na USP, um dos maiores centros de referência em reconstruções faciais e de cabeça e pescoço da América Latina, fez residência médica no Hospital Bogenhausen, em Munique, Alemanha, onde foi responsável pela preceptoria da formação naquele ano, onde atuou como cirurgião plástico no Hospital Bogenhausen, após esse período se especializou e acompanhou vários cirurgiões renomados no Brasil e nos EUA onde se aprimorou nas técnicas de cirurgia de face, inclusive o Deep Plane Facelift.<br/><br/>O Dr. Thomas é membro do corpo clínico do hospital Israelita Albert Einstein, hospital Sírio Libanês, hospital Moriah, hoje, opera todos os dias de segunda a sábado, sendo sete cirurgias por semana no único hospital 6 estrelas do Brasil, o Vila Nova Star (SP), referência máxima em infraestrutura altamente segura e tecnológica.<br/><br/></p>"},"Faq":{"faqs":{"1":{"question":"Doutor em medicina PHD pela universidade em SP","answer":"Certificado pelo Conselho Europeu de Cirurgia Plástica Doutorado (PhD) duplo pela Universidade de São Paulo, Brasil, e pela Universidade de Hamburgo, Alemanha."},"2":{"question":"Doutor em medicina PHD pela universidade em Hamburgo","answer":"Certificado pelo Conselho Alemão e pela Universidade de Hamburgo, Alemanha."},"3":{"question":"Cirurgião plástico especialista na Europa pelo board Europeu","answer":"Hoje o único Cirurgião Plástico no Brasil com Título de Especialista pelo European Board of Plastic Surgery (Conselho Europeu de Cirurgia Plástica)."},"4":{"question":"Cirurgião plástico especialista pelo Governo Alemão","answer":"Membro Especialista da Sociedade Alemã de Cirurgia Plástica."},"5":{"question":"Cirurgião plástico especialista pelo Sociedade brasileira de cirurgia plástica Membro titular da sociedade brasileira de cirurgia plástica","answer":"Membro Especialista da Sociedade Brasileira de Cirurgia Plástica."},"6":{"question":"American Academy of Facial Plastic and Reconstructive Surgery","answer":"Membro Especialista da Sociedade Americana de Cirurgia Plástica."},"7":{"question":"American society of plastic surgery","answer":"Membro da Americana de cirurgia plástica."},"8":{"question":"Membro da European Society of Plastic","answer":"Membro da European Society of Plastic, Reconstructive and Aesthetic Surgery (ESPRAS)."},"9":{"question":"Membro da International Confederation for Plastic","answer":"Membro da International Confederation for Plastic, Reconstructive and Aesthetic Surgery (IPRAS)."},"10":{"question":"Membro da Sociedade","answer":"Membro da Sociedade Alemã de Cirurgiões (DGCH)."},"11":{"question":"Membro Especialista","answer":"Membro Especialista do Conselho Europeu de Cirurgia Plástica (EBOPRAS)."},"12":{"question":"Membro da Associação","answer":"Membro da Associação dos Ex-Alunos da Cirurgia Plástica HC- FMUSP."},"13":{"question":"Membro da Associação","answer":"Membro da Associação Profissional de Médicos da Alemanha (Landesärztekammer Bayern)."},"14":{"question":"Membro da Associação","answer":"Membro da Associação Profissional de Médicos de Munique (Bezirksärztekammer München)."},"15":{"question":"Especialidade Médica","answer":"Cirurgia Plástica Estética e com foco em Cirurgias Faciais. Hoje é um dos pioneiros no Brasil na técnica inovadora de rejuvenescimento facial Deep Plane Facelift."},"16":{"question":"Cirurgia plástica detalhista e segura","answer":"Ao se formar no Brasil como cirurgião plástico, realizou nova residência médica em cirurgia plástica no Hospital Bogenhausen de Munique para obter o título de Especialista em Cirurgia Plástica e Estética pelo Governo Alemão."},"17":{"question":"Autor do Best Seller","answer":"\'A Beleza da Face\'. As informações essenciais que todo paciente deve saber para realçar os traços naturais e rejuvenescer com segurança."}}},"Serviceabout":{"h2":"Liderança no Brasil","atext":"Alto padrão nos protocolos de segurança.","p":"Dr. Thomas Benson é o único cirurgião plástico no Brasil com título de PhD na Alemanha e no Brasil e com título de especialista pelo European Board of Plastic Surgery (Conselho Europeu de Cirurgia Plástica).","item1":"Operamos no único hospital 6 estrelas do Brasil.","item2":"Melhores tecnologias.","item3":"Concierge com cuidados individuais.","item4":"Protocolos pós-cirúrgicos.","servtitle1":"Hospital Vila Nova Star","servp1":"Dr. Thomas também é membro do corpo clínico de outros grandes hospitais, como: Hospital Israelita Albert Einstein e Hospital Sírio-Libanês.","servtitle2":"Tecnologia de ponta","servp2":"Aliamos as melhores tecnologias disponíveis com a expertise da equipe, garantindo procedimentos seguros, precisos e resultados superiores.","servtitle3":"Atendimento exclusivo","servp3":"Nossa equipe de concierge oferece um serviço premium, totalmente dedicado às suas necessidades. Desde a organização de consultas e cirurgias até suporte com hospedagem, transporte e outras demandas, garantimos uma experiência tranquila e confortável.","servtitle4":"Acompanhamento e recuperação com excelência","servp4":"Seguimos protocolos pós-cirúrgicos rigorosos e exclusivos, desenvolvidos especialmente para cada paciente. Com o acompanhamento atento da equipe, nosso compromisso é garantir uma recuperação rápida e segura."},"Portfolio":{"h2":"Antes e Depois","atext":"Resultados de excelência em Deep Plane Facelift.","filters":{"all":"Casos","scars":"Cicatrizes","postSurgical":"Pós-cirúrgicos"},"portfolios1":{"description":"Clique para ver o resultado"}},"VideoContainer":{"p":"Uma mensagem especial para você!","videodesc":"Confira esses dois vídeos.","videoContainersrc":{"descr":"Clique no link para o Instagram."}},"VideoTestimonials":{"p":"Depoimentos de pacientes.","desc":"Confira alguns feedbacks de nossas queridas pacientes<br /> sobre pré e pós cirúrgico.","videodesc":"Clique para assistir ao depoimento"},"Service":{"h2":"Liderança no Brasil","atext":"Alto padrão nos protocolos de segurança.","item1":"Experiência e exclusividade.","item2":"Habilidade tecnica comprovada.","item3":"Aprimoramento diário.","item4":"Protocolos de segurança detalhados.","servtitle1":"Reconhecimento internacional","servp1":"<p>PhD no Brasil e na Alemanha pela Universidade de Hamburgo, sendo o único brasileiro reconhecido pelo Conselho Europeu de Cirurgia Plástica e pela Sociedade Alemã e Americana de Cirurgia Plástica.<br /><br /> O Dr. Thomas Benson é verdadeiramente exclusivo e escolhê-lo significa optar por um profissional cujo prestígio internacional atesta sua competência e distinção no campo das cirurgias plásticas faciais.</p>","servtitle2":"+ de 5.000 casos","servp2":"<p>O Dr. Thomas atua em consultório particular desde 2009, hoje realizando em média 350 procedimentos por ano. <br /><br /> Especialista e Cirurgião plástico na Alemanha e na Europa e PhD em ambos os países. Com uma experiência sólida e habilidade técnica comprovada em mais de 5.000 casos bem-sucedidos, o Dr. Thomas Benson é a escolha confiável para transformações faciais excepcionais.</p>","servtitle3":"Excelência e aperfeiçoamento contínuo","servp3":"<p>Comprometido com a excelência, o Dr. Thomas não apenas possui vasta experiência, mas também busca aprimoramento constante, tendo uma agenda cirúrgica diária nos melhores hospitais do país com as mais recentes inovações e técnicas. <br /><br /> Também participa em diversos congressos no Brasil e no mundo com os maiores nomes da cirurgia plástica, como participante e palestrante transmitindo seu conhecimento técnico e prático obtido ao longo de 15 anos.</p>","servtitle4":"Estrutura e prestígio exclusivos","servp4":"<p>Operamos nos melhores hospitais do Brasil incluindo e desfrutando dos centros cirúrgicos mais inovadores e tecnológico do país. <br /><br /> O Dr. Thomas Benson é verdadeiramente exclusivo e escolhê-lo significa optar por um profissional cujo prestígio internacional atesta sua competência e distinção no campo das cirurgias plásticas faciais.</p>"},"Portfolio2":{"h3":"Referência em toda a imprensa.","PressItems":{"1":{"title":"Pioneirismo no Brasil: Dr. Thomas Benson é referência na imprensa desde 2021.","article":"<p>Especialista em cirurgia da face, o médico Thomas Benson, formado pela Universidade de Hamburgo, é agora o único brasileiro com título de especialista pelo European Board of Plastic Surgery, do Conselho Europeu de Cirurgia Plástica. Na ocasião, a especialização foi feita na Alemanha e outros países da Europa e validada no Brasil.</p><p>O diploma médico alemão do cirurgião já havia sido reconhecido pela Universidade de São Paulo (USP) e, hoje, ele     também interage com a cirurgia plástica de outra forma. Atualmente, Thomas participa até como voluntário em reconstruções mamárias que são realizadas no Albert Einstein.</p><p>Clique no botão abaixo para continuar lendo esta matéria no R7.</p><br/>"},"2":{"title":"Destaque no Brasil com série ao vivo na Record em 2021 no programa \'O Hospital\'.","article":"<p>Com episódios em formato de reality, <em>O Hospital</em> registra os bastidores do Hospital Moriah, um dos maiores da América Latina e referência por seus procedimentos avançados.</p><p>A série documental tem chamado a atenção do público ao destacar a dedicação, as fragilidades, perdas e conquistas dos profissionais da área da saúde.</p><p>Clique no botão abaixo para continuar lendo esta matéria no R7.</p><br/>"},"3":{"title":"Deep Plane Facelift: Dr. Thomas Benson é destaque no Domingo Espetacular.","article":"<p>Procedimentos de harmonização facial nunca estiveram tão em evidência como na atualidade. Entre outras razões, as redes sociais e as chamadas de vídeo, impulsionadas pelo trabalho remoto durante a pandemia, fizeram com que intervenções estéticas no rosto crescessem 13,9% na comparação entre os biênios 2018-2019 e 2020-2021, de acordo com a Sociedade Internacional de Cirurgia Plástica e Estética (ISAPS).</p><p>Para falar do assunto, o ‘Domingo Espetacular’, da TV Record, entrevistou o Dr. Thomas Benson. Em programa que foi ao ar na noite desse domingo (20), o cirurgião plástico explicou como funciona o ‘deep plane facelift’, cirurgia facial mais avançada do mundo, e que é febre nos Estados Unidos.</p><p>Clique no botão abaixo para continuar lendo esta matéria na IstoÉ.</p><br/>"}},"viewArticle":"Ver matéria"},"Promo":{"h2":"Dr. Thomas lançou <em>UM BEST SELLER.</em>","featureItems2":{"1":{"title":"Best seller pela VEJA","description":"As informações essenciais que todo paciente deve saber para realçar os traços naturais e rejuvenescer com segurança."},"2":{"title":"Destaque no R7","description":"Cirurgião plástico Thomas Benson tem título da Europa reconhecido no Brasil."},"3":{"title":"Matéria no ISTOÉ","description":"Dr. Thomas Benson explica sobre a cirurgia plástica que é febre nos EUA."},"4":{"title":"Ilustre no Terra","description":"Dr. Thomas Benson explica mais detalhes sobre a técnica Deep Plane Facelift."}}},"Faq2":{"faqDataMain":{"1":{"question":"Como funcionam as consultas?","answer":"<p>As consultas na clínica do Dr. Thomas Benson são pensadas para oferecer uma experiência exclusiva e sofisticada, refletindo a excelência e o pioneirismo em cirurgia plástica facial no Brasil e no mundo.</p><p>Os pacientes podem optar por consultas presenciais, em uma clínica localizada em um bairro nobre de São Paulo, ou por consultas online, que permitem um atendimento inicial com a mesma atenção e qualidade, especialmente para pacientes de outras cidades ou países.</p><p>Durante a consulta, é realizada uma análise completa e personalizada para identificar as necessidades do paciente e avaliar a viabilidade de procedimentos, como o Deep Plane Facelift, do qual Dr. Thomas Benson é pioneiro no Brasil.</p><p>Ao chegar à clínica, o paciente é recebido por um serviço de concierge exclusivo, que assegura conforto e praticidade desde a entrada. Todo o atendimento é feito com hora marcada, evitando esperas e garantindo a privacidade e o respeito ao tempo de cada paciente.</p><p>A clínica proporciona uma experiência luxuosa e sofisticada, alinhada aos mais altos padrões internacionais de atendimento. Localizada no coração de um bairro nobre de São Paulo, o espaço foi projetado para oferecer não apenas conforto, mas também um ambiente que reflete a confiança e a excelência associadas ao nome do Dr. Thomas Benson.</p><p>Seja presencialmente ou online, cada consulta é conduzida com o compromisso de oferecer uma jornada única e transformadora, reforçando o cuidado humanizado e o alto padrão que definem o trabalho do Dr. Thomas Benson.</p>"},"2":{"question":"O Dr. Thomas atende convênio?","answer":"<p>Não, o Dr. Thomas Benson não atende convênios. Seu atendimento é focado em oferecer uma experiência exclusiva e personalizada, priorizando o mais alto padrão de qualidade e resultados excepcionais. Cada consulta e procedimento são planejados de forma individualizada, com técnicas avançadas e realizadas em um hospital 6 estrelas, garantindo a máxima segurança e sofisticação.</p><p>Para informações sobre valores e agendamentos, entre em contato com a equipe da clínica, que estará à disposição para auxiliar e proporcionar uma jornada única e transformadora.</p>"},"3":{"question":"Quais procedimentos são realizados pelo Dr?","answer":"<p>O Dr. Thomas Benson é amplamente reconhecido como referência em cirurgias faciais, com foco especial no Deep Plane Facelift, uma técnica que oferece resultados naturais e duradouros para o rejuvenescimento facial. Além disso, ele realiza procedimentos como lifting de pescoço, blefaroplastia (cirurgia das pálpebras), rinoplastia e outras intervenções que harmonizam e valorizam os traços faciais, sempre com precisão técnica e atenção aos detalhes.</p><p>Embora as cirurgias faciais sejam sua especialidade e prioridade, o Dr. Thomas Benson também possui vasta experiência em outras áreas da cirurgia plástica. Ele realiza procedimentos corporais como abdominoplastia, lipoaspiração e aumento de glúteos, cirurgias mamárias, bem como cirurgias de contorno corporal para pacientes que buscam redefinir suas proporções e melhorar sua autoestima.</p><p>Seu diferencial está na combinação de uma formação internacional sólida e uma prática diária de alto volume, com 7 cirurgias realizadas semanalmente ao longo de todo o ano. Essa experiência constante lhe confere um domínio técnico excepcional não apenas em cirurgias faciais, mas também em outras áreas da cirurgia plástica.</p><p>Independentemente do tipo de procedimento, o Dr. Thomas Benson garante uma abordagem personalizada, alinhando expectativas realistas com resultados que valorizam a beleza natural de cada paciente. Agende sua consulta para descobrir como ele pode transformar sua visão de beleza com excelência e exclusividade.</p>"},"4":{"question":"O que esperar de um resultado de uma cirurgia de face?","answer":"<p>Os resultados de uma cirurgia de face com o Dr. Thomas Benson são cuidadosamente planejados para oferecer um rejuvenescimento natural e harmonioso. A técnica do Dr. Thomas Benson, reconhecida internacionalmente, prioriza a preservação da identidade e das expressões únicas de cada paciente, garantindo que a transformação seja sutil e equilibrada, sem aquele aspecto artificial ou \'esticado\'.</p><p>A segurança é um dos pilares do trabalho do Dr. Thomas Benson. Todas as cirurgias são realizadas em um hospital 6 estrelas, considerado o mais avançado do país, seguindo protocolos rigorosos de padrão internacional. Esse cuidado assegura não apenas um procedimento seguro, mas também tranquilidade em todas as etapas do processo.</p><p>Outro diferencial é o cuidado com as cicatrizes. A abordagem meticulosa e técnica refinada do Dr. Thomas Benson garantem que as incisões sejam feitas em locais estratégicos e tratadas de forma a torná-las praticamente imperceptíveis. O objetivo é que os resultados sejam tão naturais que mesmo os sinais da cirurgia sejam quase invisíveis.</p><p>Após o procedimento, o paciente conta com protocolos pós-operatórios de excelência, desenvolvidos para uma recuperação rápida e confortável. Esses cuidados incluem um acompanhamento personalizado, orientações detalhadas e o uso de tecnologias avançadas para acelerar a cicatrização e minimizar inchaços e desconfortos.</p>"}}},"Benefits":{"h2":"Principais benefícios","h3":"Por que escolher o Dr. Thomas?","featureItems":{"1":{"title":"Resultados naturais e reais","description":"Reposicionamos as camadas, gerando resultados mais eficazes e mais bonitos, aumentando a qualidade da pele."},"2":{"title":"Cicatrizes finas e imperceptiveis","description":"Reposicionar e tirar o excesso de pele, unindo com um acompanhamento pós cirúrgico, fazem as cicatrizes ficarem imperceptíveis."},"3":{"title":"Acompanhamento pós cirurgico","description":"Contamos com uma equipe especializada e com tecnologia de ponta para fazer todo o acompanhamento pós-cirúrgico, cuidando de todo o processo de ponta a ponta."}}},"Testimonials":{"h2":"+ de 5.700 pacientes confiaram na excelência e nos protocolos do Dr. Thomas.","testimonials":{"0":{"quote":"Fiz o meu Lifting Facial com o Dr Thomas há 1 ano e estou muito satisfeita com o resultado. Ficou tão natural, que as pessoas que conheço me perguntam o que eu faço para não envelhercer! Fazer uma cirurgia no rosto é uma decisão muito difícil, pois se algo der errado não tem como esconder, sendo assim, posso afirmar que o Dr Thomas vai trazer a vcs um resultado natural e perfeito. Obrigada, Dr Thomas! Suas mãos são realmente abençoadas! Sua equipe tb é maravilhosa!","role":"Paciente"},"1":{"quote":"Completei 1 ano de cirurgia e só tenho a agradecer o Dr.Thomas Benson, o resultado continua perfeito,com certeza ele é um dos melhores cirurgiões do Brasil e do mundo. Trabalho de excelência .","role":"Paciente"},"2":{"quote":"Sempre muito atencioso, extremamente profissional e cuidadoso em deixar o paciente sem dúvidas e criar a máxima confiança nos conhecimentos técnicos e no tratamento humano e personalizado ao paciente. Excelente profissional.","role":"Paciente"}}},"Contact":{"h2":"Contato","atext":"Dê o primeiro passo. Venha viver essa experiência!","h4":"Fale conosco","consulth4":"Consultório em São Paulo"},"Footer1":{"p1":"Dr. Thomas Benson, um dos pioneiros no Brasil na inovadora técnica de rejuvenescimento facial Deep Plane Facelift.","h3":"Páginas","navigationLinks":{"0":{"text":"Sobre"},"1":{"text":"Equipe"},"2":{"text":"Blog"},"3":{"text":"Imprensa"},"4":{"text":"Pacientes no Exterior"},"5":{"text":"Cirurgias"},"6":{"text":"Antes e Depois"}},"h3_2":"Redes Sociais","p2":"Este site possui caráter informativo e educacional e segue os princípios da resolução nº 1.974/2011 do Conselho Federal de Medicina (CFM) e do código de conduta de medicina e saúde. O paciente jamais deve usar seu conteúdo para autodiagnóstico ou autotratamento. Segundo recomendação do Conselho Federal de Medicina, em caso de dúvida, o médico sempre deve ser consultado.","b1":"Todos os direitos reservados","b2":"Responsável técnico: Dr. Thomas Benson CRM. 119.278 – RQE 29279."}}');

